const RECIPES = [{"id":"paneer-butter-masala","art":"pot","hue":"#b4472c","time":35,"serves":3,"level":{"en":"Medium","hi":"मध्यम"},"diet":"veg","tags":["dinner","lunch","curry","punjabi","party"],"alias":["paneer butter masala","paneer makhani","butter paneer","paneer masala","paneer curry","पनीर बटर मसाला","पनीर मखनी","पनीर"],"title":{"en":"Paneer Butter Masala","hi":"पनीर बटर मसाला","mr":"पनीर बटर मसाला","gu":"પનીર બટર મસાલા","ta":"பனீர் பட்டர் மசாலா"},"desc":{"en":"Soft paneer cubes in a silky, mildly spiced tomato-cashew gravy finished with butter and cream.","hi":"टमाटर-काजू की मुलायम, हल्की मसालेदार ग्रेवी में पनीर, ऊपर से मक्खन और क्रीम।"},"ing":[["paneer",250,"g"],["tomato",4,"pc"],["onion",1,"pc"],["cashew",12,"pc"],["butter",3,"tbsp"],["ginger_garlic",1,"tbsp"],["chilli_powder",1.5,"tsp"],["garam_masala",1,"tsp"],["kasuri_methi",1,"tsp"],["sugar",1,"tsp"],["cream",4,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Roughly chop the tomatoes and onion. Soak the cashews in hot water for 10 minutes.","hi":"टमाटर और प्याज़ को मोटा-मोटा काट लें। काजू को 10 मिनट गरम पानी में भिगो दें।","t":600},{"en":"Heat 1 tablespoon of butter in a pan. Add onion, tomatoes and drained cashews, and cook for 8 minutes until soft.","hi":"पैन में 1 बड़ा चम्मच मक्खन गरम करें। प्याज़, टमाटर और काजू डालकर 8 मिनट तक नरम होने तक पकाएं।","t":480},{"en":"Let the mixture cool slightly, then blend it into a smooth purée.","hi":"मिश्रण को थोड़ा ठंडा करें, फिर पीसकर चिकनी प्यूरी बना लें।"},{"en":"Heat the remaining butter. Add ginger-garlic paste and sauté for 1 minute until the raw smell goes.","hi":"बचा हुआ मक्खन गरम करें। अदरक-लहसुन पेस्ट डालकर 1 मिनट तक भूनें जब तक कच्ची महक न चली जाए।","t":60},{"en":"Pour in the purée, add chilli powder, salt and sugar. Simmer for 6 minutes, stirring now and then.","hi":"प्यूरी डालें, लाल मिर्च, नमक और चीनी मिलाएं। बीच-बीच में चलाते हुए 6 मिनट धीमी आंच पर पकाएं।","t":360},{"en":"Add the paneer cubes, garam masala and crushed kasuri methi. Cook for 3 minutes.","hi":"पनीर के टुकड़े, गरम मसाला और मसली हुई कसूरी मेथी डालें। 3 मिनट पकाएं।","t":180},{"en":"Turn off the heat, stir in the cream and serve hot with naan or rice.","hi":"गैस बंद करें, क्रीम मिलाएं और नान या चावल के साथ गरमागरम परोसें।"}],"tip":{"en":"Rub kasuri methi between your palms before adding; it releases more aroma.","hi":"कसूरी मेथी डालने से पहले हथेलियों में मसल लें, खुशबू ज़्यादा आती है।"},"region":"north"},{"id":"masala-chai","art":"cup","hue":"#8a5a2b","time":10,"serves":2,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["breakfast","drink","quick","tea","evening"],"alias":["masala chai","chai","tea","adrak chai","ginger tea","मसाला चाय","चाय","अदरक वाली चाय"],"title":{"en":"Masala Chai","hi":"मसाला चाय","mr":"मसाला चहा","gu":"મસાલા ચા","ta":"மசாலா டீ"},"desc":{"en":"Strong, milky Indian tea brewed with fresh ginger and cardamom.","hi":"अदरक और इलायची वाली कड़क, दूधवाली भारतीय चाय।"},"ing":[["water",1,"cup"],["milk",1,"cup"],["tea",2,"tsp"],["ginger",1,"pc"],["cardamom",2,"pc"],["sugar",2,"tsp"]],"steps":[{"en":"Crush the ginger and cardamom lightly with a mortar or the back of a spoon.","hi":"अदरक और इलायची को खलबत्ते या चम्मच से हल्का कूट लें।"},{"en":"Boil the water in a saucepan with the crushed ginger and cardamom for 2 minutes.","hi":"पानी में कुटा अदरक और इलायची डालकर 2 मिनट उबालें।","t":120},{"en":"Add the tea leaves and sugar, and boil for 1 minute until the colour turns deep.","hi":"चाय पत्ती और चीनी डालें, 1 मिनट उबालें जब तक रंग गहरा न हो जाए।","t":60},{"en":"Pour in the milk and bring it to a boil. Let it rise twice on medium heat, about 2 minutes.","hi":"दूध डालें और उबाल आने दें। मध्यम आंच पर दो बार उफान आने दें, लगभग 2 मिनट।","t":120},{"en":"Strain into cups and serve hot.","hi":"कप में छानकर गरमागरम परोसें।"}],"tip":{"en":"For stronger chai, let it simmer one extra minute after adding milk.","hi":"कड़क चाय के लिए दूध डालने के बाद एक मिनट और पकाएं।"},"region":"north"},{"id":"veg-pulao","art":"bowl","hue":"#6f8a3a","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["lunch","dinner","rice","one-pot"],"alias":["veg pulao","vegetable pulao","pulao","pulav","pulav rice","veg rice","rice","वेज पुलाव","पुलाव","चावल"],"title":{"en":"Vegetable Pulao","hi":"वेज पुलाव","mr":"व्हेज पुलाव","gu":"વેજ પુલાવ","ta":"வெஜ் புலாவ்"},"desc":{"en":"Fragrant one-pot basmati rice cooked with whole spices and garden vegetables.","hi":"खड़े मसालों और सब्ज़ियों के साथ एक ही बर्तन में बना खुशबूदार बासमती चावल।"},"ing":[["rice",1,"cup"],["veg",1.5,"cup"],["onion",1,"pc"],["ghee",2,"tbsp"],["cumin",1,"tsp"],["bay",1,"pc"],["whole_spices",1,"tbsp"],["ginger_garlic",1,"tsp"],["green_chilli",2,"pc"],["water",2,"cup"],["salt",1,"taste"]],"steps":[{"en":"Rinse the rice 2 to 3 times and soak it in water for 20 minutes. Drain well.","hi":"चावल को 2-3 बार धोकर 20 मिनट पानी में भिगो दें। अच्छे से पानी निकाल दें।","t":1200},{"en":"Heat ghee in a pot. Add cumin, bay leaf and whole spices and let them crackle for 30 seconds.","hi":"बर्तन में घी गरम करें। जीरा, तेज पत्ता और खड़े मसाले डालें और 30 सेकंड चटकने दें।","t":30},{"en":"Add sliced onion and slit green chillies. Fry for 3 minutes until light golden.","hi":"कटा प्याज़ और चीरी हुई हरी मिर्च डालें। 3 मिनट हल्का सुनहरा होने तक भूनें।","t":180},{"en":"Stir in ginger-garlic paste and the mixed vegetables. Cook for 2 minutes.","hi":"अदरक-लहसुन पेस्ट और सब्ज़ियाँ डालें। 2 मिनट पकाएं।","t":120},{"en":"Add the drained rice and fry gently for 1 minute without breaking the grains.","hi":"भीगे चावल डालें और दाने तोड़े बिना 1 मिनट हल्के हाथ से भूनें।","t":60},{"en":"Pour in 2 cups of water and add salt. Bring to a boil, then cover and cook on low heat for 12 minutes.","hi":"2 कप पानी और नमक डालें। उबाल आने पर ढककर धीमी आंच पर 12 मिनट पकाएं।","t":720},{"en":"Turn off the heat and rest for 5 minutes. Fluff with a fork and serve with raita.","hi":"गैस बंद करके 5 मिनट रहने दें। कांटे से हल्का चलाएं और रायते के साथ परोसें।","t":300}],"tip":{"en":"Soaking makes the grains long and separate.","hi":"भिगोने से दाने लंबे और खिले-खिले बनते हैं।"},"region":"north"},{"id":"dal-tadka","art":"pot","hue":"#c78a1e","time":35,"serves":4,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["lunch","dinner","healthy","protein","curry"],"alias":["dal tadka","dal","daal","tadka dal","dal fry","yellow dal","lentil","दाल तड़का","दाल","दाल फ्राई"],"title":{"en":"Dal Tadka","hi":"दाल तड़का","mr":"डाळ तडका","gu":"દાળ તડકા","ta":"தால் தட்கா"},"desc":{"en":"Comforting yellow lentils tempered with ghee, cumin, garlic and red chillies.","hi":"घी, जीरा, लहसुन और लाल मिर्च के तड़के वाली पीली दाल।"},"ing":[["toor_dal",1,"cup"],["water",3,"cup"],["turmeric",0.5,"tsp"],["onion",1,"pc"],["tomato",1,"pc"],["ghee",2,"tbsp"],["cumin",1,"tsp"],["garlic",4,"pc"],["red_chilli",2,"pc"],["hing",1,"pinch"],["chilli_powder",0.5,"tsp"],["coriander",1,"handful"],["salt",1,"taste"]],"steps":[{"en":"Rinse the dal well. Pressure-cook it with 3 cups of water, turmeric and salt for 4 whistles, about 12 minutes.","hi":"दाल को अच्छे से धो लें। 3 कप पानी, हल्दी और नमक के साथ कुकर में 4 सीटी, लगभग 12 मिनट पकाएं।","t":720},{"en":"Once the pressure drops, whisk the dal until smooth. Add water if it is too thick.","hi":"प्रेशर निकलने पर दाल को फेंट कर चिकना कर लें। गाढ़ी हो तो पानी मिलाएं।"},{"en":"Heat 1 tablespoon of ghee. Sauté chopped onion for 3 minutes, then add tomato and cook for 3 more minutes.","hi":"1 बड़ा चम्मच घी गरम करें। कटा प्याज़ 3 मिनट भूनें, फिर टमाटर डालकर 3 मिनट और पकाएं।","t":360},{"en":"Add this to the dal and simmer for 5 minutes.","hi":"इसे दाल में मिलाएं और 5 मिनट धीमी आंच पर पकाएं।","t":300},{"en":"For the tadka, heat the remaining ghee. Add cumin, sliced garlic, dry red chillies and hing until the garlic turns golden.","hi":"तड़के के लिए बचा घी गरम करें। जीरा, कटा लहसुन, साबुत लाल मिर्च और हींग डालें, लहसुन सुनहरा होने तक।"},{"en":"Turn off the heat, add chilli powder and immediately pour the tadka over the dal. Garnish with coriander.","hi":"गैस बंद करें, लाल मिर्च पाउडर डालें और तुरंत तड़का दाल पर डालें। धनिया से सजाएं।"}],"tip":{"en":"Add chilli powder off the heat so it stays red and does not burn.","hi":"लाल मिर्च गैस बंद करके डालें ताकि रंग लाल रहे और जले नहीं।"},"region":"north"},{"id":"kanda-poha","art":"bowl","hue":"#d6a72c","time":20,"serves":2,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["breakfast","quick","maharashtrian","light"],"alias":["poha","kanda poha","pohe","kande pohe","पोहा","कांदा पोहा","पोहे"],"title":{"en":"Kanda Poha","hi":"कांदा पोहा","mr":"कांदे पोहे","gu":"કાંદા પૌંઆ","ta":"கண்டா போஹா"},"desc":{"en":"Maharashtra's favourite breakfast: flattened rice with onions, peanuts and curry leaves.","hi":"महाराष्ट्र का पसंदीदा नाश्ता: प्याज़, मूंगफली और कड़ी पत्ते वाला पोहा।"},"ing":[["poha",2,"cup"],["onion",1,"pc"],["peanuts",3,"tbsp"],["oil",2,"tbsp"],["mustard",1,"tsp"],["curry_leaves",1,"sprig"],["green_chilli",2,"pc"],["turmeric",0.5,"tsp"],["sugar",1,"tsp"],["lemon",1,"tbsp"],["coriander",1,"handful"],["salt",1,"taste"]],"steps":[{"en":"Rinse the poha in a strainer under running water for 30 seconds. Add salt, sugar and turmeric, mix gently and keep aside.","hi":"पोहे को छलनी में 30 सेकंड बहते पानी में धो लें। नमक, चीनी और हल्दी मिलाकर अलग रख दें।","t":30},{"en":"Heat oil and roast the peanuts for 2 minutes until crunchy. Take them out.","hi":"तेल गरम करके मूंगफली 2 मिनट कुरकुरी होने तक भूनें। निकाल लें।","t":120},{"en":"In the same oil, add mustard seeds. When they splutter, add curry leaves and green chillies.","hi":"उसी तेल में राई डालें। चटकने पर कड़ी पत्ता और हरी मिर्च डालें।"},{"en":"Add chopped onion and cook for 3 minutes until soft and translucent.","hi":"कटा प्याज़ डालकर 3 मिनट नरम और पारदर्शी होने तक पकाएं।","t":180},{"en":"Add the poha and peanuts, mix gently, cover and steam on low heat for 2 minutes.","hi":"पोहा और मूंगफली डालें, हल्के से मिलाएं, ढककर धीमी आंच पर 2 मिनट भाप में पकाएं।","t":120},{"en":"Finish with lemon juice and fresh coriander. Serve warm.","hi":"नींबू का रस और हरा धनिया डालें। गरम परोसें।"}],"tip":{"en":"Do not soak poha; a quick rinse keeps it fluffy, not mushy.","hi":"पोहा भिगोएं नहीं; जल्दी धोने से वह खिला-खिला रहता है।"},"region":"west"},{"id":"masala-omelette","art":"pan","hue":"#c9952c","time":10,"serves":1,"level":{"en":"Easy","hi":"आसान"},"diet":"egg","tags":["breakfast","quick","protein"],"alias":["masala omelette","omelette","omelet","egg","anda","eggs","मसाला ऑमलेट","ऑमलेट","आमलेट","अंडा"],"title":{"en":"Masala Omelette","hi":"मसाला ऑमलेट","mr":"मसाला ऑम्लेट","gu":"મસાલા ઓમલેટ","ta":"மசாலா ஆம்லெட்"},"desc":{"en":"A fluffy Indian-style omelette with onion, tomato, chilli and coriander.","hi":"प्याज़, टमाटर, मिर्च और धनिया वाला फूला हुआ देसी ऑमलेट।"},"ing":[["eggs",2,"pc"],["onion",0.5,"pc"],["tomato",0.5,"pc"],["green_chilli",1,"pc"],["coriander",1,"tbsp"],["turmeric",1,"pinch"],["butter",1,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Finely chop the onion, tomato, green chilli and coriander.","hi":"प्याज़, टमाटर, हरी मिर्च और धनिया बारीक काट लें।"},{"en":"Crack the eggs into a bowl, add salt and turmeric, and whisk for 30 seconds until frothy.","hi":"अंडे कटोरे में तोड़ें, नमक और हल्दी डालें, 30 सेकंड झागदार होने तक फेंटें।","t":30},{"en":"Mix the chopped vegetables into the eggs.","hi":"कटी सब्ज़ियाँ अंडों में मिला दें।"},{"en":"Heat butter in a pan on medium heat. Pour in the egg mixture and spread it evenly.","hi":"पैन में मध्यम आंच पर मक्खन गरम करें। अंडे का मिश्रण डालकर बराबर फैलाएं।"},{"en":"Cook for 2 minutes until the bottom is set, then flip and cook for 1 more minute.","hi":"2 मिनट तक नीचे से पकने दें, फिर पलटकर 1 मिनट और पकाएं।","t":180},{"en":"Fold and serve hot with buttered toast.","hi":"मोड़कर मक्खन लगे टोस्ट के साथ गरम परोसें।"}],"tip":{"en":"Keep the heat at medium so the omelette stays soft inside.","hi":"आंच मध्यम रखें ताकि ऑमलेट अंदर से नरम रहे।"},"region":"street"},{"id":"tomato-basil-pasta","art":"bowl","hue":"#b5372a","time":25,"serves":2,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["dinner","lunch","italian","kids"],"alias":["tomato basil pasta","pasta","arrabbiata","red sauce pasta","penne","पास्ता","रेड सॉस पास्ता"],"title":{"en":"Tomato Basil Pasta","hi":"टोमैटो बेसिल पास्ता","mr":"टोमॅटो बेसिल पास्ता","gu":"ટામેટા બેસિલ પાસ્તા","ta":"தக்காளி பேசில் பாஸ்தா"},"desc":{"en":"Penne tossed in a quick garlicky tomato sauce with basil and a little heat.","hi":"लहसुन वाली टमाटर सॉस, बेसिल और हल्की तीखी पेन्ने पास्ता।"},"ing":[["pasta",200,"g"],["tomato",4,"pc"],["garlic",5,"pc"],["olive_oil",3,"tbsp"],["chilli_flakes",1,"tsp"],["basil",1,"handful"],["sugar",0.5,"tsp"],["cheese",3,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Boil a large pot of salted water and cook the pasta for 9 minutes until al dente. Save half a cup of pasta water.","hi":"बड़े बर्तन में नमक वाला पानी उबालें और पास्ता 9 मिनट पकाएं। आधा कप पास्ता का पानी बचा लें।","t":540},{"en":"Meanwhile, finely chop the tomatoes and slice the garlic.","hi":"इस बीच टमाटर बारीक काटें और लहसुन के पतले टुकड़े करें।"},{"en":"Heat olive oil in a pan. Add garlic and chilli flakes and cook for 1 minute without browning.","hi":"पैन में ऑलिव ऑयल गरम करें। लहसुन और चिली फ्लेक्स डालें और 1 मिनट पकाएं, भूरा न होने दें।","t":60},{"en":"Add tomatoes, salt and sugar. Cook for 8 minutes until it becomes a thick sauce.","hi":"टमाटर, नमक और चीनी डालें। 8 मिनट गाढ़ी सॉस बनने तक पकाएं।","t":480},{"en":"Add the drained pasta and a splash of pasta water. Toss for 1 minute so the sauce coats the pasta.","hi":"पास्ता और थोड़ा पास्ता का पानी डालें। 1 मिनट मिलाएं ताकि सॉस पास्ता पर लिपट जाए।","t":60},{"en":"Tear in the basil, top with cheese and serve immediately.","hi":"बेसिल तोड़कर डालें, ऊपर चीज़ डालें और तुरंत परोसें।"}],"tip":{"en":"Starchy pasta water makes the sauce glossy and helps it cling.","hi":"पास्ता का पानी सॉस को चमकदार और गाढ़ा बनाता है।"},"region":"global"},{"id":"jeera-aloo","art":"pan","hue":"#a7772a","time":20,"serves":3,"level":{"en":"Easy","hi":"आसान"},"diet":"veg","tags":["lunch","dinner","quick","dry sabzi"],"alias":["jeera aloo","jeera alu","aloo jeera","potato","aloo","cumin potatoes","जीरा आलू","आलू जीरा","आलू"],"title":{"en":"Jeera Aloo","hi":"जीरा आलू","mr":"जिरा आलू","gu":"જીરા આલુ","ta":"ஜீரா ஆலு"},"desc":{"en":"Boiled potatoes tossed with cumin, green chilli and dry spices. Ready in 20 minutes.","hi":"जीरा, हरी मिर्च और सूखे मसालों में भुने उबले आलू। 20 मिनट में तैयार।"},"ing":[["potato",4,"pc"],["oil",2,"tbsp"],["cumin",1.5,"tsp"],["green_chilli",2,"pc"],["turmeric",0.5,"tsp"],["coriander_powder",1,"tsp"],["chilli_powder",0.5,"tsp"],["amchur",0.5,"tsp"],["coriander",1,"handful"],["salt",1,"taste"]],"steps":[{"en":"Boil the potatoes for 3 whistles or 15 minutes until just tender. Peel and cut into cubes.","hi":"आलू को 3 सीटी या 15 मिनट तक उबालें। छीलकर टुकड़ों में काट लें।","t":900},{"en":"Heat oil in a pan and add cumin seeds. Let them sizzle for 20 seconds.","hi":"पैन में तेल गरम करके जीरा डालें। 20 सेकंड चटकने दें।","t":20},{"en":"Add chopped green chillies, turmeric, coriander powder and chilli powder. Stir for a few seconds.","hi":"कटी हरी मिर्च, हल्दी, धनिया पाउडर और लाल मिर्च डालें। कुछ सेकंड चलाएं।"},{"en":"Add the potatoes and salt, and toss well. Cook on medium heat for 5 minutes until the edges turn crisp.","hi":"आलू और नमक डालकर अच्छे से मिलाएं। मध्यम आंच पर 5 मिनट किनारे कुरकुरे होने तक पकाएं।","t":300},{"en":"Sprinkle amchur and coriander leaves. Serve with roti or dal.","hi":"अमचूर और हरा धनिया छिड़कें। रोटी या दाल के साथ परोसें।"}],"tip":{"en":"Cool the boiled potatoes before cubing so they hold their shape.","hi":"उबले आलू ठंडे करके काटें ताकि टूटें नहीं।"},"region":"north"},{"id":"fluffy-pancakes","art":"stack","hue":"#b07a3a","time":20,"serves":2,"level":{"en":"Easy","hi":"आसान"},"diet":"egg","tags":["breakfast","sweet","kids","dessert"],"alias":["pancake","pancakes","fluffy pancakes","hotcakes","पैनकेक"],"title":{"en":"Fluffy Pancakes","hi":"फ्लफी पैनकेक","mr":"फ्लफी पॅनकेक्स","gu":"ફ્લફી પેનકેક","ta":"பஞ்சு போன்ற பான்கேக்"},"desc":{"en":"Soft, golden breakfast pancakes served with honey or maple syrup.","hi":"शहद या मेपल सिरप के साथ नरम, सुनहरे पैनकेक।"},"ing":[["flour",1,"cup"],["milk",0.75,"cup"],["eggs",1,"pc",{"en":"1 mashed ripe banana or 3 tbsp curd","hi":"1 मसला पका केला या 3 बड़े चम्मच दही"}],["sugar",2,"tbsp"],["baking_powder",2,"tsp"],["butter",2,"tbsp"],["vanilla",0.5,"tsp"],["salt",1,"pinch"],["honey",3,"tbsp"]],"steps":[{"en":"Whisk flour, sugar, baking powder and a pinch of salt in a bowl.","hi":"कटोरे में मैदा, चीनी, बेकिंग पाउडर और एक चुटकी नमक मिलाएं।"},{"en":"In another bowl, whisk milk, egg, melted butter and vanilla.","hi":"दूसरे कटोरे में दूध, अंडा, पिघला मक्खन और वनीला फेंटें।"},{"en":"Pour the wet mix into the dry mix and stir just until combined. A few lumps are fine. Rest for 5 minutes.","hi":"गीला मिश्रण सूखे में डालें और बस मिलने तक चलाएं। थोड़ी गांठें ठीक हैं। 5 मिनट रखें।","t":300},{"en":"Heat a non-stick pan on medium-low and brush it with butter.","hi":"नॉन-स्टिक पैन को मध्यम-धीमी आंच पर गरम करें और मक्खन लगाएं।"},{"en":"Pour a quarter cup of batter. Cook for 2 minutes until bubbles appear, flip and cook for 1 more minute.","hi":"चौथाई कप घोल डालें। बुलबुले आने तक 2 मिनट पकाएं, पलटें और 1 मिनट और पकाएं।","t":180},{"en":"Stack the pancakes and drizzle with honey or maple syrup.","hi":"पैनकेक एक के ऊपर एक रखें और शहद या मेपल सिरप डालें।"}],"tip":{"en":"Over-mixing makes pancakes tough; stop as soon as the flour disappears.","hi":"ज़्यादा फेंटने से पैनकेक सख्त होते हैं; सूखा आटा दिखना बंद होते ही रुक जाएं।"},"region":"global"},{"id":"chole","region":"north","art":"pot","hue":"#9c5a22","time":50,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","punjabi","protein","party"],"alias":["chole","chhole","chana masala","punjabi chole","chole masala","छोले","चना मसाला"],"title":{"en":"Punjabi Chole","hi":"पंजाबी छोले","mr":"पंजाबी छोले","gu":"પંજાબી છોલે","ta":"பஞ்சாபி சோலே"},"desc":{"en":"Dark, tangy chickpea curry from Punjab. Soak the chickpeas overnight first.","hi":"पंजाब की गहरे रंग की चटपटी छोलों की करी। छोले रात भर पहले से भिगो लें।"},"ing":[["chickpeas",1,"cup"],["tea",1,"tsp"],["onion",2,"pc"],["tomato",2,"pc"],["ginger_garlic",1,"tbsp"],["green_chilli",2,"pc"],["chilli_powder",1,"tsp"],["coriander_powder",2,"tsp"],["garam_masala",1,"tsp"],["amchur",1,"tsp"],["bay",1,"pc"],["oil",3,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Drain the soaked chickpeas. Tie the tea leaves in a small cloth or use a tea bag.","hi":"भीगे छोलों का पानी निकाल दें। चाय पत्ती को छोटे कपड़े में बांधें या टी-बैग लें।"},{"en":"Pressure cook the chickpeas with the tea bag, salt and 3 cups of water for 5 whistles, then let the pressure drop.","hi":"छोलों को टी-बैग, नमक और 3 कप पानी के साथ 5 सीटी तक प्रेशर कुक करें, फिर प्रेशर अपने आप निकलने दें।","t":1200},{"en":"Heat oil, add the bay leaf and chopped onion. Fry until deep golden, about 8 minutes.","hi":"तेल गरम करें, तेज पत्ता और कटा प्याज़ डालें। गहरा सुनहरा होने तक लगभग 8 मिनट भूनें।","t":480},{"en":"Add ginger-garlic paste and green chillies, cook 1 minute. Add chopped tomatoes and all the powdered spices except garam masala. Cook until oil separates.","hi":"अदरक-लहसुन पेस्ट और हरी मिर्च डालकर 1 मिनट पकाएं। कटे टमाटर और गरम मसाला छोड़कर सारे मसाले डालें। तेल छूटने तक पकाएं।","t":360},{"en":"Remove the tea bag. Add the chickpeas with their water, mash a few, and simmer for 10 minutes.","hi":"टी-बैग निकाल दें। छोले पानी समेत डालें, कुछ छोले मसल दें और 10 मिनट धीमी आंच पर पकाएं।","t":600},{"en":"Stir in garam masala, garnish with coriander and serve with bhature, kulcha or rice.","hi":"गरम मसाला मिलाएं, धनिया डालें और भटूरे, कुलचे या चावल के साथ परोसें।"}],"tip":{"en":"The tea bag gives chole its dark colour without changing the taste.","hi":"टी-बैग से छोलों का रंग गहरा आता है, स्वाद नहीं बदलता।"},"diet":"veg"},{"id":"rajma","region":"north","art":"pot","hue":"#8e2f25","time":55,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","punjabi","protein","comfort"],"alias":["rajma","rajma chawal","rajma masala","kidney bean curry","राजमा","राजमा चावल"],"title":{"en":"Rajma Masala","hi":"राजमा मसाला","mr":"राजमा मसाला","gu":"રાજમા મસાલા","ta":"ராஜ்மா மசாலா"},"desc":{"en":"Creamy kidney beans in an onion-tomato gravy, best with steamed rice. Soak the rajma overnight.","hi":"प्याज़-टमाटर की ग्रेवी में मलाईदार राजमा, चावल के साथ सबसे अच्छा। राजमा रात भर भिगोएं।"},"ing":[["rajma",1,"cup"],["onion",2,"pc"],["tomato",3,"pc"],["ginger_garlic",1,"tbsp"],["cumin",1,"tsp"],["turmeric",0.5,"tsp"],["chilli_powder",1,"tsp"],["coriander_powder",1.5,"tsp"],["garam_masala",1,"tsp"],["ghee",2,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Drain the soaked rajma and pressure cook with 3 cups of water and salt for 6 to 7 whistles, until very soft.","hi":"भीगे राजमा का पानी निकालकर 3 कप पानी और नमक के साथ 6-7 सीटी तक बिल्कुल नरम होने तक पकाएं।","t":1500},{"en":"Heat ghee, add cumin. When it splutters, add finely chopped onion and fry until golden.","hi":"घी गरम करें, जीरा डालें। चटकने पर बारीक कटा प्याज़ डालकर सुनहरा होने तक भूनें।","t":420},{"en":"Add ginger-garlic paste, then the puréed tomatoes, turmeric, chilli and coriander powder. Cook until thick and the oil separates.","hi":"अदरक-लहसुन पेस्ट डालें, फिर टमाटर प्यूरी, हल्दी, लाल मिर्च और धनिया पाउडर। गाढ़ा होने और तेल छूटने तक पकाएं।","t":480},{"en":"Add the rajma with its cooking water. Mash a spoonful against the side of the pot and simmer for 15 minutes.","hi":"राजमा पानी समेत डालें। एक चम्मच राजमा किनारे पर मसल दें और 15 मिनट धीमी आंच पर पकाएं।","t":900},{"en":"Add garam masala and coriander. Serve hot with rice.","hi":"गरम मसाला और धनिया डालें। चावल के साथ गरमागरम परोसें।"}],"tip":{"en":"Rajma must be fully soft before adding to the masala; undercooked beans never soften in the gravy.","hi":"मसाले में डालने से पहले राजमा पूरी तरह नरम होना चाहिए; ग्रेवी में कच्चे राजमा नरम नहीं होते।"},"diet":"veg"},{"id":"aloo-paratha","region":"north","art":"flat","hue":"#b7791f","time":40,"serves":3,"level":{"en":"Medium","hi":"मध्यम"},"tags":["breakfast","lunch","punjabi","flatbread","comfort"],"alias":["aloo paratha","alu paratha","potato paratha","stuffed paratha","paratha","आलू पराठा","पराठा"],"title":{"en":"Aloo Paratha","hi":"आलू पराठा","mr":"आलू पराठा","gu":"આલુ પરાઠા","ta":"ஆலு பராத்தா"},"desc":{"en":"Whole-wheat flatbreads stuffed with spiced mashed potato and roasted in ghee.","hi":"मसालेदार आलू भरकर घी में सेके गेहूं के पराठे।"},"ing":[["atta",2,"cup"],["potato",3,"pc"],["green_chilli",2,"pc"],["coriander",3,"tbsp"],["amchur",0.5,"tsp"],["chilli_powder",0.5,"tsp"],["ajwain",0.5,"tsp"],["ghee",4,"tbsp"],["salt",1,"taste"],["water",0.75,"cup"]],"steps":[{"en":"Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","hi":"आटे में चुटकी भर नमक और पानी डालकर नरम आटा गूंध लें। ढककर 15 मिनट रखें।","t":900},{"en":"Boil, peel and mash the potatoes. Mix in chopped green chilli, coriander, amchur, chilli powder, ajwain and salt.","hi":"आलू उबालकर छीलें और मसलें। कटी हरी मिर्च, धनिया, अमचूर, लाल मिर्च, अजवाइन और नमक मिलाएं।"},{"en":"Roll a dough ball into a small circle, place a ball of filling in the centre, pinch the edges closed and flatten.","hi":"आटे की लोई को छोटा बेलें, बीच में आलू की भरावन रखें, किनारे बंद करके चपटा करें।"},{"en":"Dust with flour and roll gently into a 7-inch paratha without pressing hard.","hi":"सूखा आटा लगाकर हल्के हाथ से 7 इंच का पराठा बेलें, ज़्यादा दबाएं नहीं।"},{"en":"Cook on a hot tawa for 1 minute, flip, spread ghee on both sides and roast until golden spots appear.","hi":"गरम तवे पर 1 मिनट सेकें, पलटें, दोनों तरफ़ घी लगाएं और सुनहरे धब्बे आने तक सेकें।","t":120},{"en":"Serve hot with curd, butter or pickle.","hi":"दही, मक्खन या अचार के साथ गरमागरम परोसें।"}],"tip":{"en":"Let the potatoes cool completely; warm filling makes the paratha tear.","hi":"आलू पूरी तरह ठंडे होने दें; गरम भरावन से पराठा फटता है।"},"diet":"veg"},{"id":"palak-paneer","region":"north","art":"pot","hue":"#3f6b33","time":35,"serves":3,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","punjabi","healthy","protein"],"alias":["palak paneer","saag paneer","spinach paneer","पालक पनीर"],"title":{"en":"Palak Paneer","hi":"पालक पनीर","mr":"पालक पनीर","gu":"પાલક પનીર","ta":"பாலக் பனீர்"},"desc":{"en":"Paneer cubes in a smooth, bright-green spinach gravy.","hi":"चिकनी, हरी पालक की ग्रेवी में पनीर के टुकड़े।"},"ing":[["spinach",1,"bunch"],["paneer",200,"g"],["onion",1,"pc"],["tomato",1,"pc"],["ginger_garlic",1,"tbsp"],["green_chilli",2,"pc"],["cumin",1,"tsp"],["garam_masala",0.5,"tsp"],["cream",2,"tbsp"],["oil",2,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Wash the spinach well. Blanch it in boiling water for 2 minutes, then plunge into cold water.","hi":"पालक अच्छी तरह धो लें। उबलते पानी में 2 मिनट रखें, फिर तुरंत ठंडे पानी में डालें।","t":120},{"en":"Blend the spinach with the green chillies into a smooth purée.","hi":"पालक को हरी मिर्च के साथ पीसकर चिकनी प्यूरी बना लें।"},{"en":"Heat oil, add cumin, then chopped onion. Fry until light golden, add ginger-garlic paste and chopped tomato, and cook until soft.","hi":"तेल गरम करें, जीरा डालें, फिर कटा प्याज़। हल्का सुनहरा होने पर अदरक-लहसुन पेस्ट और कटा टमाटर डालकर नरम होने तक पकाएं।","t":420},{"en":"Pour in the spinach purée and salt. Simmer for 4 minutes; don't cook longer or it loses its colour.","hi":"पालक प्यूरी और नमक डालें। 4 मिनट पकाएं; ज़्यादा पकाने से रंग चला जाता है।","t":240},{"en":"Add paneer cubes and garam masala, cook 2 minutes, then swirl in the cream and serve.","hi":"पनीर के टुकड़े और गरम मसाला डालें, 2 मिनट पकाएं, फिर क्रीम मिलाकर परोसें।","t":120}],"tip":{"en":"The ice-water dip after blanching keeps the gravy bright green.","hi":"उबालने के बाद ठंडे पानी में डालने से ग्रेवी हरी-भरी रहती है।"},"diet":"veg"},{"id":"punjabi-kadhi","region":"north","art":"pot","hue":"#c9a227","time":40,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","dinner","curry","punjabi","comfort"],"alias":["kadhi","punjabi kadhi","kadhi chawal","कढ़ी","पंजाबी कढ़ी","कढ़ी चावल"],"title":{"en":"Punjabi Kadhi","hi":"पंजाबी कढ़ी","mr":"पंजाबी कढी","gu":"પંજાબી કઢી","ta":"பஞ்சாபி கடி"},"desc":{"en":"Tangy yogurt and gram-flour curry, slow-simmered and finished with a spiced tadka.","hi":"खट्टे दही और बेसन की धीमी आंच पर पकी कढ़ी, ऊपर से मसालेदार तड़का।"},"ing":[["curd",1.5,"cup"],["besan",4,"tbsp"],["water",3,"cup"],["turmeric",0.5,"tsp"],["onion",1,"pc"],["ginger",1,"pc"],["cumin",1,"tsp"],["hing",1,"pinch"],["red_chilli",2,"pc"],["chilli_powder",0.5,"tsp"],["oil",2,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Whisk the curd, besan, turmeric, salt and water until there are no lumps.","hi":"दही, बेसन, हल्दी, नमक और पानी को फेंट लें ताकि गुठलियां न रहें।"},{"en":"Heat 1 tablespoon oil, add cumin, sliced onion and grated ginger. Cook for 2 minutes.","hi":"1 बड़ा चम्मच तेल गरम करें, जीरा, कटा प्याज़ और कद्दूकस अदरक डालकर 2 मिनट पकाएं।","t":120},{"en":"Pour in the curd mixture and keep stirring until it comes to a boil, so it doesn't split.","hi":"दही का घोल डालें और उबाल आने तक लगातार चलाते रहें, ताकि फटे नहीं।","t":300},{"en":"Lower the heat and simmer for 20 minutes, stirring now and then, until it thickens.","hi":"आंच धीमी करें और 20 मिनट बीच-बीच में चलाते हुए गाढ़ा होने तक पकाएं।","t":1200},{"en":"For the tadka, heat the remaining oil, add hing, dry red chillies and chilli powder, and pour over the kadhi. Garnish with coriander.","hi":"तड़के के लिए बचा तेल गरम करें, हींग, साबुत लाल मिर्च और लाल मिर्च पाउडर डालें और कढ़ी पर डालें। धनिया से सजाएं।"}],"tip":{"en":"Sour, day-old curd makes the tastiest kadhi.","hi":"एक दिन पुराना खट्टा दही सबसे स्वादिष्ट कढ़ी बनाता है।"},"diet":"veg"},{"id":"butter-chicken","region":"north","art":"pot","hue":"#c0502d","time":50,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["dinner","curry","punjabi","party","protein"],"alias":["butter chicken","murgh makhani","chicken makhani","बटर चिकन","मुर्ग मखनी"],"title":{"en":"Butter Chicken","hi":"बटर चिकन","mr":"बटर चिकन","gu":"બટર ચિકન","ta":"பட்டர் சிக்கன்"},"desc":{"en":"Marinated chicken simmered in a buttery, mildly spiced tomato-cashew sauce.","hi":"मैरीनेट किया चिकन, मक्खन वाली हल्की मसालेदार टमाटर-काजू ग्रेवी में।"},"ing":[["chicken",500,"g"],["curd",0.5,"cup"],["ginger_garlic",1.5,"tbsp"],["chilli_powder",2,"tsp"],["garam_masala",1,"tsp"],["tomato",5,"pc"],["cashew",15,"pc"],["butter",4,"tbsp"],["kasuri_methi",1,"tsp"],["sugar",1,"tsp"],["cream",4,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Mix the chicken with curd, half the ginger-garlic paste, 1 teaspoon chilli powder and salt. Marinate for at least 30 minutes.","hi":"चिकन में दही, आधा अदरक-लहसुन पेस्ट, 1 छोटा चम्मच लाल मिर्च और नमक मिलाएं। कम से कम 30 मिनट मैरीनेट करें।","t":1800},{"en":"Sear the chicken in 1 tablespoon butter on high heat until browned on all sides, about 6 minutes. Set aside.","hi":"1 बड़ा चम्मच मक्खन में तेज़ आंच पर चिकन को चारों तरफ़ से भूरा होने तक, लगभग 6 मिनट सेकें। अलग रख दें।","t":360},{"en":"Simmer the chopped tomatoes and cashews with ½ cup water for 10 minutes, then blend until smooth.","hi":"कटे टमाटर और काजू को ½ कप पानी के साथ 10 मिनट पकाएं, फिर चिकना पीस लें।","t":600},{"en":"Melt the remaining butter, add the rest of the ginger-garlic paste and chilli powder, then pour in the purée. Simmer 5 minutes.","hi":"बचा मक्खन पिघलाएं, बाकी अदरक-लहसुन पेस्ट और लाल मिर्च डालें, फिर प्यूरी डालकर 5 मिनट पकाएं।","t":300},{"en":"Add the chicken, sugar, garam masala and crushed kasuri methi. Cook covered for 10 minutes until the chicken is cooked through.","hi":"चिकन, चीनी, गरम मसाला और मसली कसूरी मेथी डालें। ढककर 10 मिनट पकाएं जब तक चिकन पूरी तरह पक न जाए।","t":600},{"en":"Turn off the heat, stir in the cream and serve with naan or jeera rice.","hi":"आंच बंद करें, क्रीम मिलाएं और नान या जीरा राइस के साथ परोसें।"}],"tip":{"en":"Cut into the thickest piece: chicken is done when there's no pink inside and the juices run clear.","hi":"सबसे मोटा टुकड़ा काटकर देखें: अंदर गुलाबी न हो और रस साफ़ निकले तो चिकन पक गया।"},"diet":"nonveg"},{"id":"aloo-gobi","region":"north","art":"pan","hue":"#c78a1e","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","dinner","dry sabzi","quick"],"alias":["aloo gobi","alu gobi","aloo gobhi","potato cauliflower","आलू गोभी"],"title":{"en":"Aloo Gobi","hi":"आलू गोभी","mr":"आलू गोबी","gu":"આલુ ગોબી","ta":"ஆலு கோபி"},"desc":{"en":"Dry-cooked potatoes and cauliflower with turmeric, cumin and ginger.","hi":"हल्दी, जीरे और अदरक के साथ सूखी आलू-गोभी की सब्ज़ी।"},"ing":[["cauliflower",1,"pc"],["potato",2,"pc"],["onion",1,"pc"],["tomato",1,"pc"],["ginger",1,"pc"],["green_chilli",1,"pc"],["cumin",1,"tsp"],["turmeric",0.5,"tsp"],["coriander_powder",1.5,"tsp"],["garam_masala",0.5,"tsp"],["oil",3,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Cut the cauliflower into florets and the potatoes into cubes. Soak the florets in warm salted water for 5 minutes and drain.","hi":"गोभी के फूल और आलू के टुकड़े काटें। गोभी को 5 मिनट गुनगुने नमक के पानी में रखकर निकाल लें।","t":300},{"en":"Heat oil, add cumin, then the onion, grated ginger and green chilli. Fry for 2 minutes.","hi":"तेल गरम करें, जीरा डालें, फिर प्याज़, कद्दूकस अदरक और हरी मिर्च। 2 मिनट भूनें।","t":120},{"en":"Add potatoes, turmeric and salt. Cover and cook for 5 minutes.","hi":"आलू, हल्दी और नमक डालें। ढककर 5 मिनट पकाएं।","t":300},{"en":"Add cauliflower, chopped tomato and coriander powder. Cover and cook on low heat for 12 minutes, stirring gently twice.","hi":"गोभी, कटा टमाटर और धनिया पाउडर डालें। ढककर धीमी आंच पर 12 मिनट पकाएं, दो बार धीरे से चलाएं।","t":720},{"en":"Uncover, sprinkle garam masala and coriander, and roast for 2 more minutes.","hi":"ढक्कन हटाएं, गरम मसाला और धनिया डालें और 2 मिनट और भूनें।","t":120}],"tip":{"en":"Don't add water; the vegetables steam in their own moisture and stay firm.","hi":"पानी न डालें; सब्ज़ियां अपनी भाप में पकती हैं और कड़क रहती हैं।"},"diet":"veg"},{"id":"gajar-halwa","region":"north","art":"bowl","hue":"#d9622b","time":60,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["sweet","dessert","winter","festive"],"alias":["gajar halwa","gajar ka halwa","carrot halwa","गाजर का हलवा","गाजर हलवा"],"title":{"en":"Gajar ka Halwa","hi":"गाजर का हलवा","mr":"गाजराचा हलवा","gu":"ગાજરનો હલવો","ta":"கேரட் அல்வா"},"desc":{"en":"Grated carrots slow-cooked in milk and ghee with cardamom and nuts.","hi":"कद्दूकस गाजर, दूध और घी में धीरे-धीरे पकाई, इलायची और मेवे के साथ।"},"ing":[["carrot",8,"pc"],["milk",3,"cup"],["sugar",0.5,"cup"],["ghee",3,"tbsp"],["cardamom",4,"pc"],["cashew",10,"pc"],["raisins",1,"tbsp"]],"steps":[{"en":"Peel and grate the carrots.","hi":"गाजर छीलकर कद्दूकस कर लें।"},{"en":"Cook the carrots with milk in a heavy pan on medium heat, stirring often, until all the milk is absorbed. About 35 minutes.","hi":"भारी कढ़ाही में गाजर और दूध मध्यम आंच पर बार-बार चलाते हुए पकाएं जब तक सारा दूध सूख न जाए। लगभग 35 मिनट।","t":2100},{"en":"Add sugar. It will melt and turn runny; keep cooking until it dries again, about 8 minutes.","hi":"चीनी डालें। यह पिघलकर पतली हो जाएगी; फिर से सूखने तक लगभग 8 मिनट पकाएं।","t":480},{"en":"Add ghee and crushed cardamom and roast for 5 minutes until glossy.","hi":"घी और कुटी इलायची डालें और चमकदार होने तक 5 मिनट भूनें।","t":300},{"en":"Fold in the cashews and raisins. Serve warm.","hi":"काजू और किशमिश मिलाएं। गुनगुना परोसें।"}],"tip":{"en":"Red winter Delhi carrots give the deepest colour and sweetness.","hi":"सर्दियों की लाल दिल्ली वाली गाजर से रंग और मिठास सबसे अच्छी आती है।"},"diet":"veg"},{"id":"sweet-lassi","region":"north","art":"glass","hue":"#d8b98a","time":5,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["drink","quick","summer","punjabi"],"alias":["lassi","sweet lassi","meethi lassi","punjabi lassi","लस्सी","मीठी लस्सी"],"title":{"en":"Sweet Lassi","hi":"मीठी लस्सी","mr":"गोड लस्सी","gu":"મીઠી લસ્સી","ta":"இனிப்பு லஸ்ஸி"},"desc":{"en":"Thick, chilled yogurt drink, frothy and lightly scented with cardamom.","hi":"गाढ़ा, ठंडा और झागदार दही का पेय, हल्की इलायची की खुशबू के साथ।"},"ing":[["curd",2,"cup"],["sugar",3,"tbsp"],["milk",0.25,"cup"],["cardamom",2,"pc"]],"steps":[{"en":"Put the chilled curd, sugar, milk and crushed cardamom in a jug.","hi":"ठंडा दही, चीनी, दूध और कुटी इलायची एक जग में डालें।"},{"en":"Whisk hard or blend for 1 minute until frothy and the sugar dissolves.","hi":"झागदार होने और चीनी घुलने तक 1 मिनट ज़ोर से फेंटें या मिक्सी चलाएं।","t":60},{"en":"Pour into glasses and serve cold, topped with a spoon of malai if you like.","hi":"गिलासों में डालें और ठंडा परोसें, चाहें तो ऊपर एक चम्मच मलाई डालें।"}],"tip":{"en":"Use thick, fresh curd; sour curd makes it tangy.","hi":"गाढ़ा, ताज़ा दही लें; खट्टे दही से लस्सी खट्टी बनेगी।"},"diet":"veg"},{"id":"rava-upma","region":"south","art":"bowl","hue":"#c8a24a","time":20,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","quick","light"],"alias":["upma","rava upma","sooji upma","uppittu","उपमा","रवा उपमा"],"title":{"en":"Rava Upma","hi":"रवा उपमा","mr":"रवा उपमा","gu":"રવા ઉપમા","ta":"ரவா உப்புமா"},"desc":{"en":"Soft, savoury semolina cooked with mustard, curry leaves and vegetables.","hi":"राई, कड़ी पत्ते और सब्ज़ियों के साथ बना नरम, नमकीन सूजी का उपमा।"},"ing":[["sooji",1,"cup"],["onion",1,"pc"],["green_chilli",2,"pc"],["ginger",1,"pc"],["veg",0.5,"cup"],["mustard",1,"tsp"],["curry_leaves",1,"sprig"],["water",2.5,"cup"],["oil",2,"tbsp"],["ghee",1,"tbsp"],["salt",1,"taste"],["lemon",1,"tbsp"]],"steps":[{"en":"Dry-roast the sooji on low heat until it smells nutty but stays pale, about 5 minutes. Set aside.","hi":"सूजी को धीमी आंच पर बिना तेल के 5 मिनट भूनें, खुशबू आए पर रंग हल्का रहे। अलग रखें।","t":300},{"en":"Heat oil, add mustard seeds. When they pop, add curry leaves, chopped onion, green chilli and grated ginger. Fry 2 minutes.","hi":"तेल गरम करें, राई डालें। चटकने पर कड़ी पत्ता, कटा प्याज़, हरी मिर्च और कद्दूकस अदरक डालकर 2 मिनट भूनें।","t":120},{"en":"Add the vegetables, water and salt. Bring to a rolling boil.","hi":"सब्ज़ियां, पानी और नमक डालें। तेज़ उबाल आने दें।","t":240},{"en":"Lower the heat and pour in the sooji slowly with one hand while stirring with the other, so no lumps form.","hi":"आंच धीमी करें और एक हाथ से सूजी धीरे-धीरे डालें, दूसरे से चलाते रहें ताकि गुठलियां न बनें।"},{"en":"Cover and cook on low for 3 minutes. Add ghee and lemon juice, fluff and serve.","hi":"ढककर धीमी आंच पर 3 मिनट पकाएं। घी और नींबू रस डालें, हल्का मिलाएं और परोसें।","t":180}],"tip":{"en":"Water ratio 1:2.5 gives soft upma; use 1:2 if you like it crumbly.","hi":"1:2.5 पानी से नरम उपमा बनता है; खिला-खिला चाहिए तो 1:2 लें।"},"diet":"veg"},{"id":"sambar","region":"south","art":"pot","hue":"#b5532a","time":45,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","protein","healthy"],"alias":["sambar","sambhar","sambar dal","सांभर","सांबर"],"title":{"en":"Sambar","hi":"सांभर","mr":"सांबार","gu":"સાંભાર","ta":"சாம்பார்"},"desc":{"en":"Toor dal and vegetable stew with tamarind and sambar powder, for rice, idli or dosa.","hi":"इमली और सांभर मसाले के साथ अरहर दाल और सब्ज़ियों का सांभर, चावल, इडली या डोसे के लिए।"},"ing":[["toor_dal",0.5,"cup"],["veg",1.5,"cup"],["onion",1,"pc"],["tomato",1,"pc"],["tamarind",1,"tbsp"],["sambar_powder",2,"tbsp"],["turmeric",0.5,"tsp"],["mustard",1,"tsp"],["curry_leaves",1,"sprig"],["red_chilli",2,"pc"],["hing",1,"pinch"],["oil",2,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Pressure cook the dal with turmeric and 2 cups of water for 4 whistles. Mash well.","hi":"दाल को हल्दी और 2 कप पानी के साथ 4 सीटी तक पकाएं। अच्छी तरह मसल लें।","t":900},{"en":"Boil the vegetables, onion and tomato in 1½ cups of water with salt until just tender, about 8 minutes.","hi":"सब्ज़ियां, प्याज़ और टमाटर 1½ कप पानी और नमक में लगभग 8 मिनट नरम होने तक उबालें।","t":480},{"en":"Add tamarind pulp and sambar powder and simmer for 5 minutes until the raw smell goes.","hi":"इमली का गूदा और सांभर मसाला डालें और कच्ची खुशबू जाने तक 5 मिनट पकाएं।","t":300},{"en":"Stir in the mashed dal and simmer for 5 more minutes, adding water if it's too thick.","hi":"मसली दाल मिलाएं और 5 मिनट और पकाएं, गाढ़ा हो तो पानी डालें।","t":300},{"en":"For tempering, heat oil, add mustard, dry red chillies, curry leaves and hing. Pour over the sambar and add coriander.","hi":"तड़के के लिए तेल गरम करें, राई, साबुत लाल मिर्च, कड़ी पत्ता और हींग डालें। सांभर पर डालें और धनिया डालें।"}],"tip":{"en":"Drumsticks, brinjal, pumpkin and okra are the classic sambar vegetables.","hi":"सहजन, बैंगन, कद्दू और भिंडी सांभर की पारंपरिक सब्ज़ियां हैं।"},"diet":"veg"},{"id":"coconut-chutney","region":"south","art":"bowl","hue":"#9db48a","time":10,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["side","quick","breakfast"],"alias":["coconut chutney","nariyal chutney","thengai chutney","नारियल चटनी","नारियल की चटनी"],"title":{"en":"Coconut Chutney","hi":"नारियल चटनी","mr":"नारळाची चटणी","gu":"નાળિયેરની ચટણી","ta":"தேங்காய் சட்னி"},"desc":{"en":"Fresh coconut ground with roasted chana and green chilli, tempered with mustard and curry leaves.","hi":"ताज़ा नारियल, भुना चना और हरी मिर्च पीसकर, राई और कड़ी पत्ते का तड़का।"},"ing":[["coconut",1,"cup"],["roasted_chana",2,"tbsp"],["green_chilli",2,"pc"],["ginger",1,"pc"],["salt",1,"taste"],["water",0.5,"cup"],["oil",1,"tsp"],["mustard",0.5,"tsp"],["curry_leaves",1,"sprig"]],"steps":[{"en":"Blend the coconut, roasted chana, green chillies, ginger and salt with water into a coarse paste.","hi":"नारियल, भुना चना, हरी मिर्च, अदरक और नमक को पानी के साथ दरदरा पीस लें।"},{"en":"Transfer to a bowl and adjust the consistency with a little more water.","hi":"कटोरी में निकालें और थोड़ा पानी डालकर गाढ़ापन ठीक करें।"},{"en":"Heat oil, add mustard and curry leaves, let them splutter and pour over the chutney.","hi":"तेल गरम करें, राई और कड़ी पत्ता डालकर चटकने दें और चटनी पर डालें।"}],"tip":{"en":"Coconut chutney spoils fast; refrigerate and use within a day.","hi":"नारियल चटनी जल्दी खराब होती है; फ्रिज में रखें और एक दिन में खत्म करें।"},"diet":"veg"},{"id":"lemon-rice","region":"south","art":"bowl","hue":"#d6b31e","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","quick","rice","tiffin","leftover"],"alias":["lemon rice","chitranna","elumichai sadam","nimbu chawal","लेमन राइस","नींबू चावल"],"title":{"en":"Lemon Rice","hi":"लेमन राइस","mr":"लिंबू भात","gu":"લીંબુ ભાત","ta":"எலுமிச்சை சாதம்"},"desc":{"en":"Leftover rice tossed with lemon, turmeric, peanuts and a crackling tempering.","hi":"बचे चावल में नींबू, हल्दी, मूंगफली और चटपटा तड़का।"},"ing":[["cooked_rice",2,"cup"],["lemon",2,"tbsp"],["peanuts",2,"tbsp"],["mustard",1,"tsp"],["curry_leaves",1,"sprig"],["green_chilli",2,"pc"],["turmeric",0.25,"tsp"],["hing",1,"pinch"],["oil",2,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Spread the cooked rice on a plate so the grains separate and cool.","hi":"पके चावल को थाली में फैला दें ताकि दाने अलग हों और ठंडे हो जाएं।"},{"en":"Heat oil, fry the peanuts until crunchy, then add mustard, curry leaves, slit green chillies and hing.","hi":"तेल गरम करें, मूंगफली कुरकुरी होने तक भूनें, फिर राई, कड़ी पत्ता, चीरी हरी मिर्च और हींग डालें।","t":120},{"en":"Turn off the heat and add turmeric so it doesn't burn.","hi":"आंच बंद करें और हल्दी डालें ताकि जले नहीं।"},{"en":"Add the rice, salt and lemon juice. Mix gently and serve.","hi":"चावल, नमक और नींबू रस डालें। हल्के हाथ से मिलाएं और परोसें।"}],"tip":{"en":"Add lemon juice off the heat; cooking it makes the rice bitter.","hi":"नींबू रस आंच बंद करके डालें; पकाने से चावल कड़वा हो जाता है।"},"diet":"veg"},{"id":"curd-rice","region":"south","art":"bowl","hue":"#cfc6b0","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","quick","rice","summer","comfort","leftover"],"alias":["curd rice","thayir sadam","dahi chawal","dahi bhaat","दही चावल","कर्ड राइस"],"title":{"en":"Curd Rice","hi":"दही चावल","mr":"दही भात","gu":"દહીં ભાત","ta":"தயிர் சாதம்"},"desc":{"en":"Cooling mashed rice and curd with a mustard and curry-leaf tempering.","hi":"राई और कड़ी पत्ते के तड़के वाला ठंडक देने वाला दही चावल।"},"ing":[["cooked_rice",2,"cup"],["curd",1,"cup"],["milk",0.25,"cup"],["mustard",0.5,"tsp"],["curry_leaves",1,"sprig"],["green_chilli",1,"pc"],["ginger",1,"pc"],["hing",1,"pinch"],["oil",1,"tsp"],["salt",1,"taste"],["coriander",1,"tbsp"]],"steps":[{"en":"Mash the warm rice lightly with a spoon.","hi":"गुनगुने चावल को चम्मच से हल्का मसल लें।"},{"en":"Mix in the curd, milk and salt.","hi":"दही, दूध और नमक मिलाएं।"},{"en":"Heat oil, add mustard, curry leaves, chopped green chilli, grated ginger and hing. Pour over the rice.","hi":"तेल गरम करें, राई, कड़ी पत्ता, कटी हरी मिर्च, कद्दूकस अदरक और हींग डालें। चावल पर डालें।"},{"en":"Stir, garnish with coriander and serve cool.","hi":"मिलाएं, धनिया डालें और ठंडा परोसें।"}],"tip":{"en":"The splash of milk stops the curd rice turning sour if you pack it for later.","hi":"थोड़ा दूध डालने से टिफ़िन में रखा दही चावल खट्टा नहीं होता।"},"diet":"veg"},{"id":"rasam","region":"south","art":"cup","hue":"#b8432f","time":25,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","dinner","soup","light","healthy"],"alias":["rasam","tomato rasam","pepper rasam","saaru","रसम"],"title":{"en":"Tomato Rasam","hi":"टमाटर रसम","mr":"टोमॅटो रसम","gu":"ટામેટા રસમ","ta":"தக்காளி ரசம்"},"desc":{"en":"Thin, peppery tomato and tamarind broth. Drink it hot or pour over rice.","hi":"पतला, काली मिर्च वाला टमाटर-इमली का रसम। गरम पिएं या चावल पर डालें।"},"ing":[["tomato",2,"pc"],["tamarind",1,"tbsp"],["black_pepper",1,"tsp"],["cumin",1,"tsp"],["garlic",4,"pc"],["turmeric",0.25,"tsp"],["mustard",0.5,"tsp"],["curry_leaves",1,"sprig"],["hing",1,"pinch"],["ghee",1,"tbsp"],["water",3,"cup"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Crush the pepper, cumin and garlic coarsely.","hi":"काली मिर्च, जीरा और लहसुन को दरदरा कूट लें।"},{"en":"Squash the chopped tomatoes with tamarind, turmeric, salt and water in a pot. Boil for 8 minutes.","hi":"कटे टमाटर को इमली, हल्दी, नमक और पानी के साथ बर्तन में मसलें। 8 मिनट उबालें।","t":480},{"en":"Add the crushed pepper mixture and simmer for 3 minutes. Don't let it boil hard.","hi":"कुटा काली मिर्च मसाला डालें और 3 मिनट धीमी आंच पर पकाएं। तेज़ उबाल न आने दें।","t":180},{"en":"Heat ghee, add mustard, curry leaves and hing, and pour into the rasam. Add coriander and serve.","hi":"घी गरम करें, राई, कड़ी पत्ता और हींग डालें और रसम में डालें। धनिया डालकर परोसें।"}],"tip":{"en":"Turn off the heat as soon as the rasam froths up; boiling makes it bitter.","hi":"रसम में झाग आते ही आंच बंद करें; ज़्यादा उबालने से कड़वा हो जाता है।"},"diet":"veg"},{"id":"kerala-veg-stew","region":"south","art":"pot","hue":"#d9c79a","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","dinner","curry","kerala","mild"],"alias":["kerala stew","vegetable stew","ishtu","veg stew","केरला स्टू","वेज स्टू"],"title":{"en":"Kerala Vegetable Stew","hi":"केरला वेज स्टू","mr":"केरळ व्हेज स्ट्यू","gu":"કેરળ વેજ સ્ટ્યૂ","ta":"கேரளா காய்கறி ஸ்டூ"},"desc":{"en":"Mild, fragrant vegetables in coconut milk with whole spices. Lovely with appam.","hi":"नारियल के दूध और खड़े मसालों में हल्की, खुशबूदार सब्ज़ियां। अप्पम के साथ बढ़िया।"},"ing":[["veg",1.5,"cup"],["potato",1,"pc"],["onion",1,"pc"],["ginger",1,"pc"],["green_chilli",3,"pc"],["whole_spices",4,"pc"],["curry_leaves",1,"sprig"],["coconut_milk",1.5,"cup"],["black_pepper",0.5,"tsp"],["oil",2,"tbsp"],["salt",1,"taste"],["water",1,"cup"]],"steps":[{"en":"Heat oil, add whole spices and curry leaves, then sliced onion, ginger and slit green chillies. Cook until soft but not brown.","hi":"तेल गरम करें, खड़े मसाले और कड़ी पत्ता डालें, फिर कटा प्याज़, अदरक और चीरी हरी मिर्च। नरम होने तक पकाएं, भूरा न होने दें।","t":240},{"en":"Add the cubed potato and vegetables with water and salt. Cover and cook until tender, about 10 minutes.","hi":"आलू और सब्ज़ियों के टुकड़े पानी और नमक के साथ डालें। ढककर नरम होने तक लगभग 10 मिनट पकाएं।","t":600},{"en":"Lower the heat and pour in the coconut milk and pepper. Warm through for 3 minutes without boiling.","hi":"आंच धीमी करें, नारियल का दूध और काली मिर्च डालें। बिना उबाले 3 मिनट गरम करें।","t":180},{"en":"Serve with appam, idiyappam or bread.","hi":"अप्पम, इडियप्पम या ब्रेड के साथ परोसें।"}],"tip":{"en":"Never boil after adding coconut milk, or it will split.","hi":"नारियल का दूध डालने के बाद उबालें नहीं, वरना फट जाएगा।"},"diet":"veg"},{"id":"chettinad-chicken","region":"south","art":"pot","hue":"#7a2f1d","time":45,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","spicy","protein","tamil"],"alias":["chettinad chicken","chicken chettinad","chettinad curry","चेट्टिनाड चिकन"],"title":{"en":"Chettinad Chicken","hi":"चेट्टिनाड चिकन","mr":"चेट्टिनाड चिकन","gu":"ચેટ્ટીનાડ ચિકન","ta":"செட்டிநாடு சிக்கன்"},"desc":{"en":"Fiery Tamil chicken curry with roasted coconut, black pepper and fennel.","hi":"भुने नारियल, काली मिर्च और सौंफ के साथ तीखी तमिल चिकन करी।"},"ing":[["chicken",500,"g"],["coconut",0.5,"cup"],["black_pepper",1.5,"tsp"],["fennel",1,"tsp"],["red_chilli",4,"pc"],["coriander_powder",2,"tsp"],["onion",2,"pc"],["tomato",2,"pc"],["ginger_garlic",1,"tbsp"],["turmeric",0.5,"tsp"],["curry_leaves",2,"sprig"],["oil",3,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Dry-roast the coconut, pepper, fennel and dry red chillies until the coconut is golden. Cool and grind to a paste with a little water.","hi":"नारियल, काली मिर्च, सौंफ और साबुत लाल मिर्च सुनहरा होने तक सूखा भूनें। ठंडा करके थोड़े पानी के साथ पेस्ट बना लें।","t":300},{"en":"Heat oil, add curry leaves and chopped onion. Fry until golden, then add ginger-garlic paste.","hi":"तेल गरम करें, कड़ी पत्ता और कटा प्याज़ डालें। सुनहरा होने पर अदरक-लहसुन पेस्ट डालें।","t":420},{"en":"Add tomatoes, turmeric, coriander powder and salt. Cook until mushy.","hi":"टमाटर, हल्दी, धनिया पाउडर और नमक डालें। गलने तक पकाएं।","t":300},{"en":"Add the chicken and sear for 5 minutes, then stir in the ground paste and 1 cup water.","hi":"चिकन डालकर 5 मिनट भूनें, फिर पिसा मसाला और 1 कप पानी मिलाएं।","t":300},{"en":"Cover and simmer for 15 minutes until the chicken is cooked through and the gravy is thick.","hi":"ढककर 15 मिनट धीमी आंच पर पकाएं जब तक चिकन पूरी तरह पक जाए और ग्रेवी गाढ़ी हो जाए।","t":900}],"tip":{"en":"Freshly roasted and ground pepper is what makes Chettinad taste like Chettinad.","hi":"ताज़ी भुनी और पिसी काली मिर्च ही चेट्टिनाड का असली स्वाद है।"},"diet":"nonveg"},{"id":"semiya-payasam","region":"south","art":"bowl","hue":"#c9a46c","time":25,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["sweet","dessert","festive"],"alias":["semiya payasam","vermicelli payasam","seviyan kheer","sevai kheer","payasam","सेवई खीर","सेवइयां","पायसम"],"title":{"en":"Semiya Payasam","hi":"सेवई पायसम","mr":"शेवयांची खीर","gu":"સેવૈયાની ખીર","ta":"சேமியா பாயசம்"},"desc":{"en":"Vermicelli simmered in sweet milk with ghee-roasted cashews and raisins.","hi":"मीठे दूध में पकी सेवई, घी में भुने काजू और किशमिश के साथ।"},"ing":[["vermicelli",0.5,"cup"],["milk",3,"cup"],["sugar",0.33,"cup"],["ghee",2,"tbsp"],["cashew",10,"pc"],["raisins",1,"tbsp"],["cardamom",3,"pc"]],"steps":[{"en":"Fry the cashews and raisins in ghee until golden. Remove.","hi":"काजू और किशमिश को घी में सुनहरा भूनकर निकाल लें।","t":120},{"en":"In the same ghee, roast the vermicelli until golden brown.","hi":"उसी घी में सेवई को सुनहरा भूरा होने तक भूनें।","t":180},{"en":"Pour in the milk and bring to a boil, then simmer until the vermicelli is soft, about 8 minutes.","hi":"दूध डालकर उबाल आने दें, फिर सेवई नरम होने तक लगभग 8 मिनट पकाएं।","t":480},{"en":"Add sugar and crushed cardamom and cook 3 more minutes.","hi":"चीनी और कुटी इलायची डालकर 3 मिनट और पकाएं।","t":180},{"en":"Stir in the nuts and raisins. Serve warm or chilled; it thickens as it cools.","hi":"मेवे और किशमिश मिलाएं। गरम या ठंडा परोसें; ठंडा होने पर गाढ़ा हो जाता है।"}],"tip":{"en":"Add sugar only after the vermicelli is soft; sugar stops it from cooking.","hi":"सेवई नरम होने के बाद ही चीनी डालें; चीनी से सेवई पकना रुक जाती है।"},"diet":"veg"},{"id":"filter-coffee","region":"south","art":"cup","hue":"#5b3a24","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["drink","breakfast","tamil"],"alias":["filter coffee","south indian coffee","kaapi","madras coffee","फ़िल्टर कॉफ़ी","कॉफ़ी","कॉफी"],"title":{"en":"Filter Coffee","hi":"फ़िल्टर कॉफ़ी","mr":"फिल्टर कॉफी","gu":"ફિલ્ટર કોફી","ta":"ஃபில்டர் காபி"},"desc":{"en":"Strong South Indian decoction mixed with frothy hot milk.","hi":"झागदार गरम दूध के साथ कड़क दक्षिण भारतीय कॉफ़ी।"},"ing":[["coffee",3,"tbsp"],["water",0.75,"cup"],["milk",1.5,"cup"],["sugar",3,"tsp"]],"steps":[{"en":"Put the coffee powder in the upper chamber of the filter and press lightly.","hi":"फ़िल्टर के ऊपरी हिस्से में कॉफ़ी पाउडर डालें और हल्का दबाएं।"},{"en":"Pour boiling water over it, close the lid and let the decoction drip for 10 minutes.","hi":"ऊपर से उबलता पानी डालें, ढक्कन बंद करें और 10 मिनट तक डिकॉक्शन टपकने दें।","t":600},{"en":"Boil the milk. Put sugar and a quarter cup of decoction into each tumbler.","hi":"दूध उबालें। हर गिलास में चीनी और चौथाई कप डिकॉक्शन डालें।"},{"en":"Add the hot milk and pour back and forth between tumbler and davara to froth it up. Serve right away.","hi":"गरम दूध डालें और गिलास-कटोरी में ऊंचाई से उलट-पलट करके झाग बनाएं। तुरंत परोसें।"}],"tip":{"en":"Coffee-chicory blends (80:20) give the classic thick, dark decoction.","hi":"कॉफ़ी-चिकोरी मिश्रण (80:20) से गाढ़ा, गहरा डिकॉक्शन बनता है।"},"diet":"veg"},{"id":"pav-bhaji","region":"west","art":"pan","hue":"#c4421f","time":40,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["dinner","street","mumbai","maharashtrian","party","kids"],"alias":["pav bhaji","paav bhaji","bhaji pav","पाव भाजी"],"title":{"en":"Pav Bhaji","hi":"पाव भाजी","mr":"पाव भाजी","gu":"પાઉં ભાજી","ta":"பாவ் பாஜி"},"desc":{"en":"Mumbai's buttery mashed-vegetable curry, served with toasted pav.","hi":"मुंबई की मक्खन वाली मसली सब्ज़ियों की भाजी, सिके पाव के साथ।"},"ing":[["potato",3,"pc"],["cauliflower",1,"cup"],["veg",1,"cup"],["capsicum",1,"pc"],["onion",2,"pc"],["tomato",4,"pc"],["ginger_garlic",1,"tbsp"],["pav_bhaji_masala",2,"tbsp"],["chilli_powder",1,"tsp"],["butter",5,"tbsp"],["lemon",1,"tbsp"],["salt",1,"taste"],["coriander",3,"tbsp"],["pav",8,"pc"]],"steps":[{"en":"Pressure cook the potatoes, cauliflower and mixed vegetables with a cup of water for 3 whistles. Mash well.","hi":"आलू, गोभी और मिक्स सब्ज़ियों को एक कप पानी के साथ 3 सीटी तक पकाएं। अच्छी तरह मसल लें।","t":600},{"en":"Melt 3 tablespoons butter on a wide pan. Fry one chopped onion and the capsicum for 3 minutes, then add ginger-garlic paste.","hi":"चौड़े तवे पर 3 बड़े चम्मच मक्खन पिघलाएं। एक कटा प्याज़ और शिमला मिर्च 3 मिनट भूनें, फिर अदरक-लहसुन पेस्ट डालें।","t":180},{"en":"Add the tomatoes, pav bhaji masala, chilli powder and salt. Cook until the tomatoes turn mushy.","hi":"टमाटर, पाव भाजी मसाला, लाल मिर्च और नमक डालें। टमाटर गलने तक पकाएं।","t":360},{"en":"Add the mashed vegetables and a little water. Mash everything together with a masher and simmer for 8 minutes.","hi":"मसली सब्ज़ियां और थोड़ा पानी डालें। मैशर से सब मसलें और 8 मिनट पकाएं।","t":480},{"en":"Slit the pav, spread butter and toast on the pan until crisp.","hi":"पाव बीच से काटें, मक्खन लगाएं और तवे पर कुरकुरा सेकें।","t":120},{"en":"Top the bhaji with butter, coriander and lemon juice. Serve with the pav and chopped raw onion.","hi":"भाजी पर मक्खन, धनिया और नींबू रस डालें। पाव और कटे कच्चे प्याज़ के साथ परोसें।"}],"tip":{"en":"A spoon of the bhaji masala on the toasting pav makes it taste like the street stalls.","hi":"पाव सेकते समय उस पर थोड़ा भाजी मसाला लगाने से ठेले जैसा स्वाद आता है।"},"diet":"veg"},{"id":"sabudana-khichdi","region":"west","art":"bowl","hue":"#d7c58f","time":20,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","fasting","maharashtrian","quick"],"alias":["sabudana khichdi","sabudana","sago khichdi","sabudana khichadi","साबूदाना खिचड़ी","साबूदाना"],"title":{"en":"Sabudana Khichdi","hi":"साबूदाना खिचड़ी","mr":"साबुदाणा खिचडी","gu":"સાબુદાણા ખીચડી","ta":"ஜவ்வரிசி கிச்சடி"},"desc":{"en":"Soft, chewy sago pearls with potato and crushed peanuts. A favourite fasting dish. Soak the sabudana for 4 hours first.","hi":"आलू और कुटी मूंगफली के साथ नरम साबूदाना। व्रत का पसंदीदा नाश्ता। साबूदाना 4 घंटे पहले भिगो लें।"},"ing":[["sabudana",1,"cup"],["potato",1,"pc"],["peanuts",0.33,"cup"],["cumin",1,"tsp"],["green_chilli",2,"pc"],["ghee",2,"tbsp"],["sugar",1,"tsp"],["lemon",1,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Rinse the sabudana and soak it in just enough water to cover for 4 hours, until a pearl crushes easily between your fingers.","hi":"साबूदाना धोकर उतने ही पानी में 4 घंटे भिगोएं जितने में डूब जाए, जब तक दाना उंगलियों में आसानी से न दबे।"},{"en":"Dry-roast the peanuts, cool, and crush coarsely. Mix with the drained sabudana, salt and sugar.","hi":"मूंगफली भूनें, ठंडी करके दरदरी कूटें। छने साबूदाने में नमक और चीनी के साथ मिलाएं।"},{"en":"Heat ghee, add cumin and green chillies, then the diced boiled potato. Fry for 2 minutes.","hi":"घी गरम करें, जीरा और हरी मिर्च डालें, फिर उबले आलू के टुकड़े। 2 मिनट भूनें।","t":120},{"en":"Add the sabudana mix and stir gently on low heat until the pearls turn translucent, about 5 minutes.","hi":"साबूदाना मिश्रण डालें और धीमी आंच पर हल्के हाथ से चलाएं जब तक दाने पारदर्शी न हो जाएं, लगभग 5 मिनट।","t":300},{"en":"Finish with lemon juice and coriander and serve hot.","hi":"नींबू रस और धनिया डालकर गरमागरम परोसें।"}],"tip":{"en":"Too much soaking water makes it mushy; the pearls should look separate after soaking.","hi":"ज़्यादा पानी से साबूदाना चिपचिपा होता है; भीगने के बाद दाने अलग-अलग दिखने चाहिए।"},"diet":"veg"},{"id":"khaman-dhokla","region":"west","art":"stack","hue":"#e0b92f","time":30,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["breakfast","snack","gujarati","steamed","healthy"],"alias":["dhokla","khaman","khaman dhokla","ढोकला","खमण","खमन ढोकला"],"title":{"en":"Khaman Dhokla","hi":"खमण ढोकला","mr":"खमण ढोकळा","gu":"ખમણ ઢોકળા","ta":"காமன் டோக்ளா"},"desc":{"en":"Spongy steamed gram-flour cake from Gujarat, soaked in a sweet-sour tempering.","hi":"गुजरात का स्पंजी, भाप में पका बेसन का ढोकला, खट्टे-मीठे तड़के के साथ।"},"ing":[["besan",1.5,"cup"],["sugar",1,"tbsp"],["lemon",2,"tbsp"],["turmeric",0.25,"tsp"],["ginger",1,"pc"],["green_chilli",3,"pc"],["eno",1,"tsp"],["water",1,"cup"],["oil",2,"tbsp"],["mustard",1,"tsp"],["curry_leaves",1,"sprig"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Start heating water in a steamer and grease a round tin.","hi":"स्टीमर में पानी गरम करना शुरू करें और एक गोल डिब्बे में तेल लगाएं।"},{"en":"Whisk the besan with ¾ cup water, sugar, half the lemon juice, turmeric, grated ginger, 1 chopped green chilli, 1 tbsp oil and salt into a smooth batter.","hi":"बेसन में ¾ कप पानी, चीनी, आधा नींबू रस, हल्दी, कद्दूकस अदरक, 1 कटी हरी मिर्च, 1 बड़ा चम्मच तेल और नमक मिलाकर चिकना घोल बनाएं।"},{"en":"Add the Eno, stir quickly in one direction, and pour into the tin right away.","hi":"ईनो डालें, एक ही दिशा में जल्दी मिलाएं और तुरंत डिब्बे में डालें।"},{"en":"Steam on medium heat for 15 minutes, until a toothpick comes out clean.","hi":"मध्यम आंच पर 15 मिनट भाप में पकाएं, जब तक टूथपिक साफ़ न निकले।","t":900},{"en":"Heat the remaining oil, add mustard, curry leaves and slit chillies. Add ¼ cup water, the rest of the lemon juice and a pinch of sugar, then pour over the cut dhokla.","hi":"बचा तेल गरम करें, राई, कड़ी पत्ता और चीरी मिर्च डालें। ¼ कप पानी, बचा नींबू रस और चुटकी चीनी डालें, फिर कटे ढोकले पर डालें।"},{"en":"Garnish with coriander and serve with green chutney.","hi":"धनिया से सजाएं और हरी चटनी के साथ परोसें।"}],"tip":{"en":"Don't open the steamer for the first 12 minutes or the dhokla will sink.","hi":"पहले 12 मिनट स्टीमर न खोलें वरना ढोकला बैठ जाएगा।"},"diet":"veg"},{"id":"methi-thepla","region":"west","art":"flat","hue":"#6e8b3d","time":35,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["breakfast","travel","gujarati","flatbread","healthy"],"alias":["thepla","methi thepla","methi paratha","थेपला","मेथी थेपला"],"title":{"en":"Methi Thepla","hi":"मेथी थेपला","mr":"मेथी थेपला","gu":"મેથીના થેપલા","ta":"வெந்தய தேப்லா"},"desc":{"en":"Soft Gujarati flatbreads with fresh fenugreek and spices. They keep well for travel.","hi":"हरी मेथी और मसालों वाले नरम गुजराती थेपले, सफ़र के लिए बढ़िया।"},"ing":[["atta",2,"cup"],["methi_leaves",1,"cup"],["besan",2,"tbsp"],["curd",0.33,"cup"],["turmeric",0.5,"tsp"],["chilli_powder",1,"tsp"],["ajwain",0.5,"tsp"],["sugar",1,"tsp"],["oil",4,"tbsp"],["salt",1,"taste"],["water",0.25,"cup"]],"steps":[{"en":"Wash and finely chop the methi leaves.","hi":"मेथी के पत्ते धोकर बारीक काट लें।"},{"en":"Mix atta, besan, methi, curd, spices, sugar, salt and 1 tablespoon oil. Knead into a soft dough with a little water and rest 10 minutes.","hi":"आटा, बेसन, मेथी, दही, मसाले, चीनी, नमक और 1 बड़ा चम्मच तेल मिलाएं। थोड़े पानी से नरम आटा गूंधें और 10 मिनट रखें।","t":600},{"en":"Roll small balls into thin 6-inch rounds.","hi":"छोटी लोइयों को 6 इंच की पतली रोटी जैसा बेलें।"},{"en":"Cook on a hot tawa with a little oil on both sides until golden spots appear, about 1 minute per side.","hi":"गरम तवे पर दोनों तरफ़ थोड़ा तेल लगाकर सुनहरे धब्बे आने तक सेकें, हर तरफ़ लगभग 1 मिनट।","t":120},{"en":"Stack in a cloth to keep soft. Serve with curd, pickle or chai.","hi":"नरम रखने के लिए कपड़े में रखें। दही, अचार या चाय के साथ परोसें।"}],"tip":{"en":"Kneading with curd instead of water keeps theplas soft for 2 to 3 days.","hi":"पानी की जगह दही से गूंधने पर थेपले 2-3 दिन तक नरम रहते हैं।"},"diet":"veg"},{"id":"goan-fish-curry","region":"west","art":"pot","hue":"#c95f1b","time":35,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","goan","coastal","protein"],"alias":["goan fish curry","fish curry","goan curry","xitt kodi","गोवा फिश करी","फिश करी","मछली करी"],"title":{"en":"Goan Fish Curry","hi":"गोवा फिश करी","mr":"गोवन फिश करी","gu":"ગોવા ફિશ કરી","ta":"கோவா மீன் குழம்பு"},"desc":{"en":"Tangy coconut curry with Kashmiri chillies and tamarind, the way it's made along the Konkan coast.","hi":"कश्मीरी मिर्च और इमली वाली खट्टी नारियल करी, कोंकण तट के अंदाज़ में।"},"ing":[["fish",500,"g"],["coconut",1,"cup"],["red_chilli",6,"pc"],["coriander_powder",2,"tsp"],["cumin",1,"tsp"],["turmeric",0.5,"tsp"],["garlic",4,"pc"],["tamarind",1,"tbsp"],["onion",1,"pc"],["green_chilli",2,"pc"],["oil",2,"tbsp"],["salt",1,"taste"],["water",1.5,"cup"]],"steps":[{"en":"Rub the fish pieces with turmeric and salt and set aside for 10 minutes.","hi":"मछली के टुकड़ों पर हल्दी और नमक लगाकर 10 मिनट रखें।","t":600},{"en":"Grind the coconut, dry red chillies, coriander powder, cumin, garlic and tamarind with water into a smooth paste.","hi":"नारियल, साबुत लाल मिर्च, धनिया पाउडर, जीरा, लहसुन और इमली को पानी के साथ चिकना पीस लें।"},{"en":"Heat oil, fry the sliced onion until soft, then add the paste and slit green chillies. Cook for 5 minutes.","hi":"तेल गरम करें, कटा प्याज़ नरम होने तक भूनें, फिर पेस्ट और चीरी हरी मिर्च डालें। 5 मिनट पकाएं।","t":300},{"en":"Add the remaining water and salt and bring to a gentle boil.","hi":"बचा पानी और नमक डालें और हल्का उबाल आने दें।","t":180},{"en":"Slide in the fish and simmer for 6 to 8 minutes without stirring, just shake the pan. Serve with rice.","hi":"मछली डालें और 6-8 मिनट धीमी आंच पर पकाएं, चलाएं नहीं, सिर्फ़ बर्तन हिलाएं। चावल के साथ परोसें।","t":420}],"tip":{"en":"Fish is cooked when it turns opaque and flakes easily with a fork.","hi":"मछली अपारदर्शी हो जाए और कांटे से आसानी से टूटे, तो पक गई।"},"diet":"nonveg"},{"id":"sooji-sheera","region":"west","art":"bowl","hue":"#dca43a","time":20,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["sweet","dessert","festive","quick","maharashtrian"],"alias":["sheera","sooji halwa","suji halwa","rava sheera","kesari","शीरा","सूजी का हलवा","हलवा"],"title":{"en":"Sooji Sheera","hi":"सूजी का हलवा","mr":"रव्याचा शिरा","gu":"સોજીનો શીરો","ta":"ரவா கேசரி"},"desc":{"en":"Ghee-roasted semolina pudding with milk, cardamom and nuts, ready in 20 minutes.","hi":"घी में भुनी सूजी, दूध, इलायची और मेवों वाला हलवा, 20 मिनट में तैयार।"},"ing":[["sooji",0.5,"cup"],["ghee",4,"tbsp"],["sugar",0.5,"cup"],["milk",1,"cup"],["water",0.5,"cup"],["cardamom",3,"pc"],["cashew",8,"pc"],["raisins",1,"tbsp"],["saffron",1,"pinch"]],"steps":[{"en":"Heat the milk and water together with saffron and keep it hot.","hi":"दूध और पानी को केसर के साथ गरम करें और गरम ही रखें।"},{"en":"Fry the cashews and raisins in ghee and remove. Add sooji to the ghee and roast on low heat until golden and fragrant, about 7 minutes.","hi":"काजू-किशमिश घी में भूनकर निकाल लें। उसी घी में सूजी धीमी आंच पर सुनहरी और खुशबूदार होने तक लगभग 7 मिनट भूनें।","t":420},{"en":"Carefully pour in the hot milk while stirring; it will splutter. Cook until absorbed.","hi":"सावधानी से गरम दूध डालें और चलाते रहें; छींटे आएंगे। सोखने तक पकाएं।","t":120},{"en":"Add sugar and cardamom and stir until the sheera leaves the sides of the pan.","hi":"चीनी और इलायची डालें और कढ़ाही छोड़ने तक चलाएं।","t":180},{"en":"Mix in the nuts and serve warm.","hi":"मेवे मिलाएं और गरम परोसें।"}],"tip":{"en":"The milk must be hot when it goes in; cold milk makes lumps.","hi":"दूध गरम होना चाहिए; ठंडे दूध से गुठलियां बनती हैं।"},"diet":"veg"},{"id":"shrikhand","region":"west","art":"bowl","hue":"#e7c25b","time":15,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["sweet","dessert","festive","gujarati","maharashtrian","summer"],"alias":["shrikhand","kesar shrikhand","elaichi shrikhand","श्रीखंड"],"title":{"en":"Kesar Shrikhand","hi":"केसर श्रीखंड","mr":"केशर श्रीखंड","gu":"કેસર શ્રીખંડ","ta":"கேசர் ஸ்ரீகண்ட்"},"desc":{"en":"Thick strained yogurt sweetened with sugar, saffron and cardamom. Hang the curd for 6 hours first.","hi":"चीनी, केसर और इलायची वाला गाढ़ा छना दही। दही 6 घंटे पहले टांग दें।"},"ing":[["curd",3,"cup"],["sugar",0.5,"cup"],["saffron",1,"pinch"],["milk",1,"tbsp"],["cardamom",4,"pc"],["cashew",6,"pc"]],"steps":[{"en":"Tie the curd in a muslin cloth and hang it in the fridge for 6 hours, until thick like cream cheese.","hi":"दही को मलमल के कपड़े में बांधकर फ्रिज में 6 घंटे टांगें, जब तक क्रीम चीज़ जैसा गाढ़ा न हो जाए।"},{"en":"Soak the saffron in warm milk for 10 minutes.","hi":"केसर को गुनगुने दूध में 10 मिनट भिगोएं।","t":600},{"en":"Whisk the hung curd with sugar until smooth and the sugar dissolves.","hi":"टंगे दही को चीनी के साथ चिकना होने और चीनी घुलने तक फेंटें।"},{"en":"Mix in the saffron milk and cardamom powder, top with chopped cashews and chill before serving.","hi":"केसर वाला दूध और इलायची पाउडर मिलाएं, ऊपर कटे काजू डालें और ठंडा करके परोसें।"}],"tip":{"en":"Use powdered sugar for the smoothest texture.","hi":"सबसे चिकनी बनावट के लिए पिसी चीनी लें।"},"diet":"veg"},{"id":"macher-jhol","region":"east","art":"pot","hue":"#c26a1c","time":35,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["lunch","dinner","curry","bengali","protein","light"],"alias":["macher jhol","maacher jhol","bengali fish curry","fish jhol","माछेर झोल","बंगाली फिश करी"],"title":{"en":"Macher Jhol","hi":"माछेर झोल","mr":"माछेर झोल","gu":"માછેર ઝોલ","ta":"மாச்சர் ஜோல்"},"desc":{"en":"Light Bengali fish and potato curry flavoured with mustard oil, cumin and ginger.","hi":"सरसों तेल, जीरे और अदरक वाली हल्की बंगाली मछली-आलू की करी।"},"ing":[["fish",500,"g"],["potato",2,"pc"],["tomato",1,"pc"],["mustard_oil",4,"tbsp"],["nigella",0.5,"tsp"],["ginger",1,"pc"],["cumin",1,"tsp"],["turmeric",1,"tsp"],["chilli_powder",1,"tsp"],["green_chilli",3,"pc"],["water",2,"cup"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Rub the fish with half the turmeric and salt. Heat mustard oil until it smokes lightly, then fry the fish 2 minutes per side. Set aside.","hi":"मछली पर आधी हल्दी और नमक लगाएं। सरसों तेल हल्का धुआं आने तक गरम करें, मछली हर तरफ़ 2 मिनट तलें। अलग रखें।","t":240},{"en":"In the same oil, fry the potato wedges until golden. Remove.","hi":"उसी तेल में आलू के टुकड़े सुनहरे होने तक तलें। निकाल लें।","t":300},{"en":"Add nigella seeds and slit green chillies, then a paste of ginger, cumin, remaining turmeric and chilli powder. Fry for 2 minutes.","hi":"कलौंजी और चीरी हरी मिर्च डालें, फिर अदरक, जीरा, बाकी हल्दी और लाल मिर्च का पेस्ट। 2 मिनट भूनें।","t":120},{"en":"Add chopped tomato and cook until soft. Add the potatoes, water and salt. Simmer until the potatoes are tender, about 10 minutes.","hi":"कटा टमाटर डालकर नरम करें। आलू, पानी और नमक डालें। आलू नरम होने तक लगभग 10 मिनट पकाएं।","t":600},{"en":"Slide in the fish and simmer for 5 minutes. Garnish with coriander and serve with steamed rice.","hi":"मछली डालें और 5 मिनट धीमी आंच पर पकाएं। धनिया डालें और चावल के साथ परोसें।","t":300}],"tip":{"en":"Heat mustard oil until it just smokes; it mellows the sharpness.","hi":"सरसों तेल को हल्का धुआं आने तक गरम करें; इससे इसकी तेज़ी कम होती है।"},"diet":"nonveg"},{"id":"aloo-posto","region":"east","art":"pan","hue":"#cdb98a","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","bengali","dry sabzi"],"alias":["aloo posto","alu posto","posto","potato poppy seed","आलू पोस्तो"],"title":{"en":"Aloo Posto","hi":"आलू पोस्तो","mr":"आलू पोस्तो","gu":"આલુ પોસ્તો","ta":"ஆலு போஸ்தோ"},"desc":{"en":"Potatoes in a creamy poppy-seed paste with green chilli and mustard oil. Simple Bengali comfort food.","hi":"खसखस के मलाईदार पेस्ट, हरी मिर्च और सरसों तेल में आलू। सादा बंगाली खाना।"},"ing":[["potato",3,"pc"],["poppy_seeds",4,"tbsp"],["green_chilli",3,"pc"],["nigella",0.5,"tsp"],["mustard_oil",2,"tbsp"],["turmeric",0.25,"tsp"],["water",0.5,"cup"],["salt",1,"taste"]],"steps":[{"en":"Soak the poppy seeds in hot water for 20 minutes, then grind with 2 green chillies into a smooth paste.","hi":"खसखस को 20 मिनट गरम पानी में भिगोएं, फिर 2 हरी मिर्च के साथ चिकना पीस लें।","t":1200},{"en":"Heat mustard oil, add nigella and the remaining slit chilli, then the potato cubes with turmeric and salt. Fry for 3 minutes.","hi":"सरसों तेल गरम करें, कलौंजी और बची चीरी मिर्च डालें, फिर आलू के टुकड़े, हल्दी और नमक। 3 मिनट भूनें।","t":180},{"en":"Add half a cup of water, cover and cook until the potatoes are just soft, about 10 minutes.","hi":"आधा कप पानी डालें, ढककर आलू नरम होने तक लगभग 10 मिनट पकाएं।","t":600},{"en":"Stir in the poppy paste and cook uncovered for 3 to 4 minutes until it coats the potatoes. Drizzle a little raw mustard oil on top.","hi":"खसखस का पेस्ट मिलाएं और बिना ढके 3-4 मिनट पकाएं जब तक आलू पर लिपट न जाए। ऊपर थोड़ा कच्चा सरसों तेल डालें।","t":210}],"tip":{"en":"Eat aloo posto with plain rice and dal; it's meant to be mild.","hi":"आलू पोस्तो सादे चावल और दाल के साथ खाएं; यह हल्का ही होता है।"},"diet":"veg"},{"id":"ghugni","region":"east","art":"bowl","hue":"#b78a3c","time":45,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["snack","breakfast","street","bengali","protein"],"alias":["ghugni","ghughni","matar ghugni","घुघनी","घुगनी"],"title":{"en":"Ghugni","hi":"घुगनी","mr":"घुगनी","gu":"ઘુગની","ta":"குக்னி"},"desc":{"en":"Dried yellow peas simmered with potato and spices, topped with onion and tamarind. Soak the peas overnight.","hi":"आलू और मसालों के साथ पकी सूखी मटर, ऊपर प्याज़ और इमली। मटर रात भर भिगोएं।"},"ing":[["yellow_peas",1,"cup"],["potato",1,"pc"],["onion",2,"pc"],["tomato",1,"pc"],["ginger_garlic",1,"tbsp"],["cumin",1,"tsp"],["turmeric",0.5,"tsp"],["chilli_powder",1,"tsp"],["garam_masala",0.5,"tsp"],["tamarind_chutney",2,"tbsp"],["oil",2,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Pressure cook the soaked peas with the potato cubes, turmeric, salt and 3 cups of water for 3 whistles.","hi":"भीगी मटर को आलू के टुकड़ों, हल्दी, नमक और 3 कप पानी के साथ 3 सीटी तक पकाएं।","t":600},{"en":"Heat oil, add cumin, then one chopped onion. Fry until golden and add ginger-garlic paste.","hi":"तेल गरम करें, जीरा डालें, फिर एक कटा प्याज़। सुनहरा होने पर अदरक-लहसुन पेस्ट डालें।","t":360},{"en":"Add tomato and chilli powder and cook until soft.","hi":"टमाटर और लाल मिर्च डालकर नरम होने तक पकाएं।","t":240},{"en":"Add the peas with their liquid and simmer for 10 minutes until thick. Stir in garam masala.","hi":"मटर पानी समेत डालें और गाढ़ा होने तक 10 मिनट पकाएं। गरम मसाला मिलाएं।","t":600},{"en":"Serve topped with the remaining chopped onion, tamarind chutney and coriander.","hi":"ऊपर बचा कटा प्याज़, इमली की चटनी और धनिया डालकर परोसें।"}],"tip":{"en":"Mash a few peas into the gravy to make it thick and creamy.","hi":"कुछ मटर ग्रेवी में मसल दें, गाढ़ी और मलाईदार बनेगी।"},"diet":"veg"},{"id":"payesh","region":"east","art":"bowl","hue":"#e2cfa5","time":50,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["sweet","dessert","festive","bengali"],"alias":["payesh","payas","rice kheer","chawal ki kheer","kheer","पायेश","खीर","चावल की खीर"],"title":{"en":"Payesh (Rice Kheer)","hi":"पायेश (चावल की खीर)","mr":"तांदळाची खीर","gu":"ચોખાની ખીર","ta":"அரிசி பாயசம்"},"desc":{"en":"Bengali rice pudding slow-cooked in milk, sweetened with jaggery or sugar.","hi":"दूध में धीमी आंच पर पकी बंगाली चावल की खीर, गुड़ या चीनी से मीठी।"},"ing":[["rice",0.25,"cup"],["milk",4,"cup"],["jaggery",0.33,"cup"],["cardamom",3,"pc"],["bay",1,"pc"],["ghee",1,"tsp"],["cashew",8,"pc"],["raisins",1,"tbsp"]],"steps":[{"en":"Wash the rice and rub it with the ghee.","hi":"चावल धोकर उस पर घी लगा दें।"},{"en":"Bring the milk to a boil with the bay leaf and cardamom in a heavy pot.","hi":"भारी बर्तन में दूध को तेज पत्ते और इलायची के साथ उबालें।","t":420},{"en":"Add the rice and simmer on low heat, stirring often, until the rice is soft and the milk thickens, about 35 minutes.","hi":"चावल डालें और धीमी आंच पर बार-बार चलाते हुए पकाएं जब तक चावल नरम और दूध गाढ़ा न हो जाए, लगभग 35 मिनट।","t":2100},{"en":"Turn off the heat and let it cool for 5 minutes, then stir in the jaggery so the milk doesn't curdle.","hi":"आंच बंद करें और 5 मिनट ठंडा होने दें, फिर गुड़ मिलाएं ताकि दूध न फटे।","t":300},{"en":"Add cashews and raisins. Serve warm or chilled.","hi":"काजू और किशमिश डालें। गरम या ठंडा परोसें।"}],"tip":{"en":"Always add jaggery off the heat; it can split hot milk.","hi":"गुड़ हमेशा आंच बंद करके डालें; गरम दूध में यह फट सकता है।"},"diet":"veg"},{"id":"veg-momos","region":"east","art":"stack","hue":"#c9b9a0","time":50,"serves":4,"level":{"en":"Medium","hi":"मध्यम"},"tags":["snack","street","steamed","northeast","party"],"alias":["momos","momo","veg momos","dumplings","steamed momos","मोमो","मोमोज़","मोमोस"],"title":{"en":"Veg Momos","hi":"वेज मोमोज़","mr":"व्हेज मोमोज","gu":"વેજ મોમોઝ","ta":"வெஜ் மோமோஸ்"},"desc":{"en":"Steamed dumplings with a juicy cabbage-carrot filling, as made across the North-East and the hills.","hi":"पत्ता गोभी-गाजर की रसीली भरावन वाले भाप में पके मोमोज़, जैसे पूर्वोत्तर और पहाड़ों में बनते हैं।"},"ing":[["flour",2,"cup"],["cabbage",2,"cup"],["carrot",1,"pc"],["onion",1,"pc"],["garlic",4,"pc"],["ginger",1,"pc"],["spring_onion",3,"pc"],["soy_sauce",1,"tbsp"],["black_pepper",0.5,"tsp"],["oil",2,"tbsp"],["salt",1,"taste"],["water",0.6,"cup"]],"steps":[{"en":"Knead the flour with a pinch of salt, 1 teaspoon oil and water into a firm, smooth dough. Cover and rest for 20 minutes.","hi":"मैदे में चुटकी नमक, 1 छोटा चम्मच तेल और पानी डालकर सख्त, चिकना आटा गूंधें। ढककर 20 मिनट रखें।","t":1200},{"en":"Finely chop the cabbage, carrot, onion, garlic, ginger and spring onions. Squeeze excess water from the cabbage.","hi":"पत्ता गोभी, गाजर, प्याज़, लहसुन, अदरक और हरा प्याज़ बारीक काटें। गोभी का पानी निचोड़ दें।"},{"en":"Stir-fry the garlic and ginger in oil for 30 seconds, add the vegetables and cook on high heat for 3 minutes. Season with soy sauce, pepper and salt, then cool.","hi":"तेल में लहसुन-अदरक 30 सेकंड भूनें, सब्ज़ियां डालकर तेज़ आंच पर 3 मिनट पकाएं। सोया सॉस, काली मिर्च और नमक डालें, फिर ठंडा करें।","t":210},{"en":"Roll small dough balls into thin 3-inch circles, place a spoon of filling in the centre and pleat the edges closed.","hi":"छोटी लोइयों को 3 इंच की पतली पूरी बेलें, बीच में एक चम्मच भरावन रखें और किनारे चुन्नट बनाकर बंद करें।"},{"en":"Steam on a greased tray for 10 to 12 minutes until the wrappers look translucent. Serve with red chilli chutney.","hi":"तेल लगी ट्रे पर 10-12 मिनट भाप दें जब तक ऊपरी परत पारदर्शी न दिखे। लाल मिर्च की चटनी के साथ परोसें।","t":660}],"tip":{"en":"Keep the dough covered while you shape; dry wrappers crack.","hi":"मोमो बनाते समय आटा ढककर रखें; सूखा आटा फटता है।"},"diet":"veg"},{"id":"thukpa","region":"east","art":"bowl","hue":"#a5602e","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["dinner","soup","noodles","northeast","comfort","winter"],"alias":["thukpa","noodle soup","tibetan noodle soup","थुकपा"],"title":{"en":"Veg Thukpa","hi":"वेज थुकपा","mr":"व्हेज थुकपा","gu":"વેજ થુકપા","ta":"வெஜ் துக்பா"},"desc":{"en":"Warming Himalayan noodle soup with vegetables, garlic and ginger.","hi":"सब्ज़ियों, लहसुन और अदरक वाला गरमाहट देने वाला हिमालयी नूडल सूप।"},"ing":[["noodles",150,"g"],["cabbage",1,"cup"],["carrot",1,"pc"],["capsicum",1,"pc"],["onion",1,"pc"],["tomato",1,"pc"],["garlic",4,"pc"],["ginger",1,"pc"],["green_chilli",1,"pc"],["soy_sauce",1,"tbsp"],["water",5,"cup"],["oil",1,"tbsp"],["salt",1,"taste"],["spring_onion",2,"pc"]],"steps":[{"en":"Boil the noodles until just cooked, drain and rinse in cold water.","hi":"नूडल्स को बस पकने तक उबालें, छानें और ठंडे पानी से धो लें।","t":300},{"en":"Heat oil, add chopped garlic, ginger, green chilli and sliced onion. Fry for 2 minutes.","hi":"तेल गरम करें, कटा लहसुन, अदरक, हरी मिर्च और कटा प्याज़ डालें। 2 मिनट भूनें।","t":120},{"en":"Add the tomato, carrot, cabbage and capsicum and stir-fry for 3 minutes.","hi":"टमाटर, गाजर, पत्ता गोभी और शिमला मिर्च डालकर 3 मिनट तेज़ आंच पर भूनें।","t":180},{"en":"Pour in the water, soy sauce and salt. Simmer for 8 minutes.","hi":"पानी, सोया सॉस और नमक डालें। 8 मिनट पकाएं।","t":480},{"en":"Divide the noodles into bowls, ladle the hot soup over and top with spring onions.","hi":"नूडल्स को कटोरियों में डालें, ऊपर गरम सूप डालें और हरा प्याज़ छिड़कें।"}],"tip":{"en":"Keep noodles and soup separate until serving so the noodles don't go soggy.","hi":"परोसने तक नूडल्स और सूप अलग रखें ताकि नूडल्स गल न जाएं।"},"diet":"veg"},{"id":"bhel-puri","region":"street","art":"bowl","hue":"#d08a2c","time":10,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["snack","street","quick","mumbai","evening"],"alias":["bhel","bhel puri","bhelpuri","भेल","भेल पूरी","भेलपुरी"],"title":{"en":"Bhel Puri","hi":"भेल पूरी","mr":"भेळ","gu":"ભેળ","ta":"பேல் பூரி"},"desc":{"en":"Crunchy puffed rice tossed with chutneys, onion, tomato and sev. Mix just before eating.","hi":"चटनियों, प्याज़, टमाटर और सेव के साथ कुरकुरे मुरमुरे। खाने से ठीक पहले मिलाएं।"},"ing":[["puffed_rice",3,"cup"],["potato",1,"pc"],["onion",1,"pc"],["tomato",1,"pc"],["green_chutney",2,"tbsp"],["tamarind_chutney",3,"tbsp"],["peanuts",2,"tbsp"],["chaat_masala",1,"tsp"],["lemon",1,"tbsp"],["sev",0.5,"cup"],["coriander",2,"tbsp"]],"steps":[{"en":"Boil and dice the potato. Finely chop the onion, tomato and coriander.","hi":"आलू उबालकर छोटे टुकड़े करें। प्याज़, टमाटर और धनिया बारीक काटें।"},{"en":"In a large bowl, combine the puffed rice, potato, onion, tomato and peanuts.","hi":"बड़े कटोरे में मुरमुरे, आलू, प्याज़, टमाटर और मूंगफली मिलाएं।"},{"en":"Add both chutneys, chaat masala and lemon juice. Toss quickly.","hi":"दोनों चटनियां, चाट मसाला और नींबू रस डालें। जल्दी से मिलाएं।"},{"en":"Top with sev and coriander and serve immediately.","hi":"ऊपर सेव और धनिया डालें और तुरंत परोसें।"}],"tip":{"en":"If the murmura isn't crisp, toast it in a dry pan for 2 minutes first.","hi":"मुरमुरे कुरकुरे न हों तो पहले सूखी कढ़ाही में 2 मिनट भून लें।"},"diet":"veg"},{"id":"egg-bhurji","region":"street","art":"pan","hue":"#e0a82e","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","dinner","quick","protein","street"],"alias":["egg bhurji","anda bhurji","scrambled eggs","masala scrambled eggs","अंडा भुर्जी","एग भुर्जी"],"title":{"en":"Egg Bhurji","hi":"अंडा भुर्जी","mr":"अंडा भुर्जी","gu":"એગ ભુર્જી","ta":"முட்டை புர்ஜி"},"desc":{"en":"Spicy Indian scrambled eggs with onion, tomato and green chilli. Great with pav or roti.","hi":"प्याज़, टमाटर और हरी मिर्च वाली मसालेदार अंडा भुर्जी। पाव या रोटी के साथ बढ़िया।"},"ing":[["eggs",4,"pc"],["onion",1,"pc"],["tomato",1,"pc"],["green_chilli",2,"pc"],["turmeric",0.25,"tsp"],["chilli_powder",0.5,"tsp"],["butter",1.5,"tbsp"],["salt",1,"taste"],["coriander",2,"tbsp"]],"steps":[{"en":"Melt the butter and fry the chopped onion and green chilli until soft, about 3 minutes.","hi":"मक्खन पिघलाएं और कटा प्याज़ और हरी मिर्च नरम होने तक लगभग 3 मिनट भूनें।","t":180},{"en":"Add the tomato, turmeric, chilli powder and salt and cook until the tomato softens.","hi":"टमाटर, हल्दी, लाल मिर्च और नमक डालें और टमाटर नरम होने तक पकाएं।","t":120},{"en":"Lower the heat, crack in the eggs and stir continuously until softly set, about 2 minutes.","hi":"आंच धीमी करें, अंडे तोड़कर डालें और लगातार चलाते हुए हल्का जमने तक लगभग 2 मिनट पकाएं।","t":120},{"en":"Stir in coriander and serve with buttered pav or roti.","hi":"धनिया मिलाएं और मक्खन लगे पाव या रोटी के साथ परोसें।"}],"tip":{"en":"Take it off the heat while still a little moist; it keeps cooking on the plate.","hi":"थोड़ी नम रहते ही आंच से उतार लें; प्लेट में भी पकती रहती है।"},"diet":"egg"},{"id":"bombay-sandwich","region":"street","art":"stack","hue":"#6f9a43","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","snack","street","mumbai","quick","kids"],"alias":["bombay sandwich","veg sandwich","mumbai sandwich","sandwich","बॉम्बे सैंडविच","सैंडविच"],"title":{"en":"Bombay Veg Sandwich","hi":"बॉम्बे वेज सैंडविच","mr":"बॉम्बे सँडविच","gu":"બોમ્બે સેન્ડવીચ","ta":"பாம்பே சாண்ட்விச்"},"desc":{"en":"Layered sandwich with green chutney, potato, cucumber and tomato, dusted with chaat masala.","hi":"हरी चटनी, आलू, खीरा और टमाटर की परतों वाला सैंडविच, ऊपर चाट मसाला।"},"ing":[["bread",4,"pc"],["butter",1,"tbsp"],["green_chutney",2,"tbsp"],["potato",1,"pc"],["cucumber",1,"pc"],["tomato",1,"pc"],["onion",1,"pc"],["chaat_masala",1,"tsp"],["cheese",2,"tbsp"]],"steps":[{"en":"Boil and thinly slice the potato. Slice the cucumber, tomato and onion into thin rounds.","hi":"आलू उबालकर पतला काटें। खीरा, टमाटर और प्याज़ के पतले गोल टुकड़े काटें।"},{"en":"Spread butter and green chutney on all the bread slices.","hi":"सभी ब्रेड स्लाइस पर मक्खन और हरी चटनी लगाएं।"},{"en":"Layer potato, cucumber, tomato and onion on two slices, sprinkling chaat masala between layers. Add grated cheese if you like.","hi":"दो स्लाइस पर आलू, खीरा, टमाटर और प्याज़ की परतें लगाएं, बीच-बीच में चाट मसाला छिड़कें। चाहें तो कद्दूकस चीज़ डालें।"},{"en":"Cover with the remaining slices, press gently, and toast or grill until golden if you want it hot. Cut and serve.","hi":"बाकी स्लाइस से ढकें, हल्का दबाएं, और गरम चाहिए तो सुनहरा होने तक सेकें। काटकर परोसें।","t":240}],"tip":{"en":"Pat the tomato and cucumber dry so the bread doesn't get soggy.","hi":"टमाटर और खीरे को कपड़े से सुखा लें ताकि ब्रेड गीली न हो।"},"diet":"veg"},{"id":"aloo-tikki","region":"street","art":"pan","hue":"#b9802d","time":30,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["snack","street","evening","kids","party"],"alias":["aloo tikki","alu tikki","potato patties","tikki","आलू टिक्की","टिक्की"],"title":{"en":"Aloo Tikki","hi":"आलू टिक्की","mr":"आलू टिक्की","gu":"આલુ ટિક્કી","ta":"ஆலு டிக்கி"},"desc":{"en":"Crisp, golden potato patties. Eat with chutneys or turn them into tikki chaat.","hi":"कुरकुरी सुनहरी आलू की टिक्की। चटनी के साथ खाएं या टिक्की चाट बनाएं।"},"ing":[["potato",4,"pc"],["cornflour",2,"tbsp"],["green_chilli",2,"pc"],["ginger",1,"pc"],["coriander",3,"tbsp"],["chaat_masala",1,"tsp"],["chilli_powder",0.5,"tsp"],["salt",1,"taste"],["oil",3,"tbsp"],["green_chutney",3,"tbsp"]],"steps":[{"en":"Boil, peel and grate the potatoes. Let them cool completely.","hi":"आलू उबालें, छीलें और कद्दूकस करें। पूरी तरह ठंडा होने दें।"},{"en":"Mix in the cornflour, chopped chilli, grated ginger, coriander, chaat masala, chilli powder and salt.","hi":"कॉर्नफ्लोर, कटी मिर्च, कद्दूकस अदरक, धनिया, चाट मसाला, लाल मिर्च और नमक मिलाएं।"},{"en":"Shape into 8 flat patties with oiled hands.","hi":"तेल लगे हाथों से 8 चपटी टिक्कियां बनाएं।"},{"en":"Shallow-fry on medium heat for about 4 minutes per side until deep golden and crisp.","hi":"मध्यम आंच पर हर तरफ़ लगभग 4 मिनट गहरी सुनहरी और कुरकुरी होने तक तलें।","t":480},{"en":"Serve hot with green chutney.","hi":"हरी चटनी के साथ गरमागरम परोसें।"}],"tip":{"en":"Don't flip too early; let a crust form first or the tikki breaks.","hi":"जल्दी न पलटें; पहले परत बनने दें वरना टिक्की टूट जाएगी।"},"diet":"veg"},{"id":"masala-noodles","region":"street","art":"bowl","hue":"#d39a2a","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["snack","quick","kids","noodles","dinner"],"alias":["masala noodles","desi noodles","veg noodles","maggi masala","मसाला नूडल्स","नूडल्स"],"title":{"en":"Desi Masala Noodles","hi":"देसी मसाला नूडल्स","mr":"मसाला नूडल्स","gu":"મસાલા નૂડલ્સ","ta":"மசாலா நூடுல்ஸ்"},"desc":{"en":"Quick Indian-style noodles with vegetables, tomato and a little garam masala.","hi":"सब्ज़ियों, टमाटर और थोड़े गरम मसाले वाले झटपट देसी नूडल्स।"},"ing":[["noodles",150,"g"],["onion",1,"pc"],["capsicum",1,"pc"],["tomato",1,"pc"],["veg",0.5,"cup"],["green_chilli",1,"pc"],["chilli_powder",0.5,"tsp"],["garam_masala",0.5,"tsp"],["turmeric",0.25,"tsp"],["ketchup",2,"tbsp"],["oil",1.5,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Boil the noodles until just tender, drain and toss with a few drops of oil.","hi":"नूडल्स को बस नरम होने तक उबालें, छानें और कुछ बूंद तेल मिला दें।","t":240},{"en":"Heat oil and fry the onion, capsicum, green chilli and vegetables on high heat for 3 minutes.","hi":"तेल गरम करें और प्याज़, शिमला मिर्च, हरी मिर्च और सब्ज़ियां तेज़ आंच पर 3 मिनट भूनें।","t":180},{"en":"Add the tomato, turmeric, chilli powder, garam masala and salt. Cook for 2 minutes.","hi":"टमाटर, हल्दी, लाल मिर्च, गरम मसाला और नमक डालें। 2 मिनट पकाएं।","t":120},{"en":"Add the noodles and ketchup and toss well for 1 minute. Serve hot.","hi":"नूडल्स और केचप डालें और 1 मिनट अच्छी तरह मिलाएं। गरम परोसें।","t":60}],"tip":{"en":"Rinse boiled noodles in cold water to stop them sticking together.","hi":"उबले नूडल्स ठंडे पानी से धोएं ताकि आपस में चिपकें नहीं।"},"diet":"veg"},{"id":"paneer-tikka","region":"street","art":"pan","hue":"#c4512a","time":40,"serves":3,"level":{"en":"Medium","hi":"मध्यम"},"tags":["snack","starter","party","protein","punjabi"],"alias":["paneer tikka","tikka","paneer starter","पनीर टिक्का"],"title":{"en":"Paneer Tikka","hi":"पनीर टिक्का","mr":"पनीर टिक्का","gu":"પનીર ટિક્કા","ta":"பனீர் டிக்கா"},"desc":{"en":"Paneer and vegetables in a spiced yogurt marinade, charred on a pan, oven or grill.","hi":"मसालेदार दही में मैरीनेट पनीर और सब्ज़ियां, तवे, ओवन या ग्रिल पर सेकी हुई।"},"ing":[["paneer",250,"g"],["capsicum",1,"pc"],["onion",1,"pc"],["curd",0.5,"cup"],["besan",1,"tbsp"],["ginger_garlic",1,"tbsp"],["chilli_powder",1.5,"tsp"],["garam_masala",1,"tsp"],["kasuri_methi",1,"tsp"],["lemon",1,"tbsp"],["oil",2,"tbsp"],["salt",1,"taste"],["chaat_masala",1,"tsp"]],"steps":[{"en":"Cut the paneer, capsicum and onion into large cubes.","hi":"पनीर, शिमला मिर्च और प्याज़ के बड़े टुकड़े काटें।"},{"en":"Roast the besan in a dry pan for 1 minute, then mix it with curd, ginger-garlic paste, spices, kasuri methi, lemon juice, 1 tablespoon oil and salt.","hi":"बेसन को सूखी कढ़ाही में 1 मिनट भूनें, फिर दही, अदरक-लहसुन पेस्ट, मसाले, कसूरी मेथी, नींबू रस, 1 बड़ा चम्मच तेल और नमक मिलाएं।"},{"en":"Coat the paneer and vegetables in the marinade and rest for 30 minutes.","hi":"पनीर और सब्ज़ियों पर मैरिनेड लगाएं और 30 मिनट रखें।","t":1800},{"en":"Thread onto skewers, or place directly on a hot greased pan. Cook on high heat, turning, until charred in spots, about 8 minutes.","hi":"सीख में पिरोएं, या सीधे गरम तेल लगे तवे पर रखें। तेज़ आंच पर पलटते हुए जगह-जगह भुनने तक लगभग 8 मिनट सेकें।","t":480},{"en":"Sprinkle chaat masala and lemon juice and serve with green chutney.","hi":"चाट मसाला और नींबू रस छिड़कें और हरी चटनी के साथ परोसें।"}],"tip":{"en":"Roasted besan stops the marinade from sliding off and adds a smoky flavour.","hi":"भुना बेसन मैरिनेड को टिकाए रखता है और सोंधा स्वाद देता है।"},"diet":"veg"},{"id":"masala-chaas","region":"street","art":"glass","hue":"#a7b88a","time":5,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["drink","quick","summer","gujarati","healthy"],"alias":["chaas","masala chaas","buttermilk","chhachh","mattha","majjige","छाछ","मसाला छाछ","मट्ठा"],"title":{"en":"Masala Chaas","hi":"मसाला छाछ","mr":"मसाला ताक","gu":"મસાલા છાશ","ta":"மசாலா மோர்"},"desc":{"en":"Cooling spiced buttermilk with roasted cumin, ginger and mint.","hi":"भुने जीरे, अदरक और पुदीने वाली ठंडी मसाला छाछ।"},"ing":[["curd",1,"cup"],["water",2,"cup"],["cumin",1,"tsp"],["ginger",1,"pc"],["green_chilli",1,"pc"],["mint",1,"handful"],["coriander",1,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Dry-roast the cumin seeds for 30 seconds and crush them.","hi":"जीरे को 30 सेकंड सूखा भूनें और कूट लें।","t":30},{"en":"Blend the curd, water, ginger, green chilli, mint, coriander and salt until frothy.","hi":"दही, पानी, अदरक, हरी मिर्च, पुदीना, धनिया और नमक को झागदार होने तक मिक्सी में चलाएं।"},{"en":"Stir in the roasted cumin and serve chilled.","hi":"भुना जीरा मिलाएं और ठंडा परोसें।"}],"tip":{"en":"A pinch of black salt (kala namak) gives the classic street-style taste.","hi":"चुटकी भर काला नमक डालने से ठेले वाली छाछ जैसा स्वाद आता है।"},"diet":"veg"},{"id":"veg-fried-rice","region":"global","art":"bowl","hue":"#8a9a3a","time":20,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["lunch","dinner","quick","rice","indo-chinese","leftover"],"alias":["fried rice","veg fried rice","vegetable fried rice","chinese rice","फ्राइड राइस","वेज फ्राइड राइस"],"title":{"en":"Veg Fried Rice","hi":"वेज फ्राइड राइस","mr":"व्हेज फ्राइड राइस","gu":"વેજ ફ્રાઈડ રાઈસ","ta":"வெஜ் ஃப்ரைடு ரைஸ்"},"desc":{"en":"Indo-Chinese fried rice with crunchy vegetables, garlic and soy sauce. Best with day-old rice.","hi":"कुरकुरी सब्ज़ियों, लहसुन और सोया सॉस वाला इंडो-चाइनीज़ फ्राइड राइस। एक दिन पुराने चावल से सबसे अच्छा।"},"ing":[["cooked_rice",3,"cup"],["veg",1,"cup"],["cabbage",0.5,"cup"],["capsicum",1,"pc"],["spring_onion",3,"pc"],["garlic",5,"pc"],["soy_sauce",1.5,"tbsp"],["vinegar",1,"tsp"],["black_pepper",0.5,"tsp"],["oil",2,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Finely chop the garlic and all the vegetables. Separate the white and green parts of the spring onion.","hi":"लहसुन और सारी सब्ज़ियां बारीक काटें। हरे प्याज़ का सफ़ेद और हरा हिस्सा अलग करें।"},{"en":"Heat oil on the highest heat, add garlic and the spring onion whites and fry for 30 seconds.","hi":"सबसे तेज़ आंच पर तेल गरम करें, लहसुन और हरे प्याज़ का सफ़ेद हिस्सा डालकर 30 सेकंड भूनें।","t":30},{"en":"Add the vegetables and toss for 2 to 3 minutes so they stay crunchy.","hi":"सब्ज़ियां डालें और 2-3 मिनट उछालते हुए भूनें ताकि कुरकुरी रहें।","t":150},{"en":"Add the rice, soy sauce, vinegar, pepper and salt and toss for 2 minutes.","hi":"चावल, सोया सॉस, सिरका, काली मिर्च और नमक डालें और 2 मिनट मिलाते हुए भूनें।","t":120},{"en":"Finish with the spring onion greens and serve hot.","hi":"हरे प्याज़ की पत्तियां डालें और गरम परोसें।"}],"tip":{"en":"Cold, day-old rice fries best; fresh rice turns mushy.","hi":"ठंडे, एक दिन पुराने चावल सबसे अच्छे बनते हैं; ताज़े चावल गीले हो जाते हैं।"},"diet":"veg"},{"id":"chilli-paneer","region":"global","art":"pan","hue":"#a8321e","time":30,"serves":3,"level":{"en":"Medium","hi":"मध्यम"},"tags":["dinner","starter","indo-chinese","party","spicy"],"alias":["chilli paneer","chili paneer","paneer chilli","चिली पनीर"],"title":{"en":"Chilli Paneer","hi":"चिली पनीर","mr":"चिली पनीर","gu":"ચિલી પનીર","ta":"சில்லி பனீர்"},"desc":{"en":"Crisp paneer tossed with peppers and onion in a spicy, tangy soy-chilli sauce.","hi":"कुरकुरा पनीर, शिमला मिर्च और प्याज़ के साथ तीखी-खट्टी सोया-चिली सॉस में।"},"ing":[["paneer",250,"g"],["cornflour",3,"tbsp"],["capsicum",1,"pc"],["onion",1,"pc"],["garlic",5,"pc"],["ginger",1,"pc"],["green_chilli",3,"pc"],["soy_sauce",1.5,"tbsp"],["vinegar",1,"tbsp"],["ketchup",2,"tbsp"],["black_pepper",0.5,"tsp"],["spring_onion",2,"pc"],["oil",3,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Toss the paneer cubes with 2 tablespoons cornflour, salt and pepper.","hi":"पनीर के टुकड़ों पर 2 बड़े चम्मच कॉर्नफ्लोर, नमक और काली मिर्च लपेटें।"},{"en":"Shallow-fry the paneer in hot oil until golden and crisp on all sides. Remove.","hi":"पनीर को गरम तेल में चारों तरफ़ से सुनहरा और कुरकुरा होने तक तलें। निकाल लें।","t":300},{"en":"In 1 tablespoon oil on high heat, fry chopped garlic, ginger and green chillies for 30 seconds. Add cubed onion and capsicum and toss for 2 minutes.","hi":"1 बड़ा चम्मच तेल तेज़ आंच पर गरम करें, कटा लहसुन, अदरक और हरी मिर्च 30 सेकंड भूनें। प्याज़ और शिमला मिर्च के टुकड़े डालकर 2 मिनट भूनें।","t":150},{"en":"Add soy sauce, vinegar and ketchup. Mix the remaining cornflour with ¼ cup water and pour in; stir until glossy.","hi":"सोया सॉस, सिरका और केचप डालें। बचे कॉर्नफ्लोर को ¼ कप पानी में घोलकर डालें; चमकदार होने तक चलाएं।","t":60},{"en":"Add the paneer, toss to coat, and garnish with spring onion.","hi":"पनीर डालें, सॉस में लपेटें और हरे प्याज़ से सजाएं।"}],"tip":{"en":"For a dry starter skip the cornflour slurry; for gravy add ½ cup water instead.","hi":"सूखे स्टार्टर के लिए कॉर्नफ्लोर का घोल न डालें; ग्रेवी के लिए ½ कप पानी डालें।"},"diet":"veg"},{"id":"tomato-soup","region":"global","art":"cup","hue":"#c9342a","time":30,"serves":3,"level":{"en":"Easy","hi":"आसान"},"tags":["dinner","soup","kids","winter","light"],"alias":["tomato soup","cream of tomato","tamatar soup","टमाटर सूप","टोमैटो सूप"],"title":{"en":"Creamy Tomato Soup","hi":"टमाटर सूप","mr":"टोमॅटो सूप","gu":"ટામેટા સૂપ","ta":"தக்காளி சூப்"},"desc":{"en":"Velvety tomato soup with garlic and black pepper, finished with a swirl of cream.","hi":"लहसुन और काली मिर्च वाला मखमली टमाटर सूप, ऊपर क्रीम।"},"ing":[["tomato",6,"pc"],["onion",1,"pc"],["garlic",4,"pc"],["butter",1.5,"tbsp"],["bay",1,"pc"],["sugar",1,"tsp"],["black_pepper",0.5,"tsp"],["water",2,"cup"],["cream",2,"tbsp"],["salt",1,"taste"]],"steps":[{"en":"Melt the butter, add the bay leaf, chopped onion and garlic, and cook until soft, about 4 minutes.","hi":"मक्खन पिघलाएं, तेज पत्ता, कटा प्याज़ और लहसुन डालकर नरम होने तक लगभग 4 मिनट पकाएं।","t":240},{"en":"Add the chopped tomatoes, salt and water. Cover and simmer for 15 minutes.","hi":"कटे टमाटर, नमक और पानी डालें। ढककर 15 मिनट पकाएं।","t":900},{"en":"Remove the bay leaf, cool slightly and blend until smooth. Strain for an extra-silky soup.","hi":"तेज पत्ता निकालें, थोड़ा ठंडा करके चिकना पीस लें। ज़्यादा मुलायम सूप के लिए छान लें।"},{"en":"Return to the pot, add sugar and pepper and simmer for 3 minutes.","hi":"वापस बर्तन में डालें, चीनी और काली मिर्च डालकर 3 मिनट पकाएं।","t":180},{"en":"Serve hot with a swirl of cream and toast or croutons.","hi":"ऊपर क्रीम डालकर टोस्ट या क्रूटॉन के साथ गरम परोसें।"}],"tip":{"en":"The pinch of sugar balances sour tomatoes; taste first and adjust.","hi":"चुटकी भर चीनी खट्टे टमाटरों को संतुलित करती है; पहले चखकर देखें।"},"diet":"veg"},{"id":"overnight-oats","region":"global","art":"glass","hue":"#b08a5a","time":5,"serves":1,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","healthy","no-cook","quick","protein"],"alias":["overnight oats","oats","soaked oats","ओवरनाइट ओट्स","ओट्स"],"title":{"en":"Overnight Oats","hi":"ओवरनाइट ओट्स","mr":"ओव्हरनाइट ओट्स","gu":"ઓવરનાઈટ ઓટ્સ","ta":"ஓவர்நைட் ஓட்ஸ்"},"desc":{"en":"No-cook breakfast: oats soaked overnight in milk and curd with banana and honey.","hi":"बिना पकाए नाश्ता: दूध और दही में रात भर भीगे ओट्स, केले और शहद के साथ।"},"ing":[["oats",0.5,"cup"],["milk",0.5,"cup"],["curd",0.25,"cup"],["honey",1,"tbsp"],["banana",1,"pc"],["cinnamon_powder",0.25,"tsp"],["peanuts",1,"tbsp"]],"steps":[{"en":"In a jar, mix the oats, milk, curd, honey and cinnamon.","hi":"एक जार में ओट्स, दूध, दही, शहद और दालचीनी मिलाएं।"},{"en":"Close the lid and refrigerate overnight, or at least 4 hours.","hi":"ढक्कन बंद करके रात भर, या कम से कम 4 घंटे फ्रिज में रखें।"},{"en":"In the morning, stir, add a splash of milk if thick, and top with sliced banana and crushed peanuts.","hi":"सुबह मिलाएं, गाढ़ा हो तो थोड़ा दूध डालें, ऊपर कटा केला और कुटी मूंगफली डालें।"}],"tip":{"en":"Keeps for 3 days in the fridge; make a few jars on Sunday.","hi":"फ्रिज में 3 दिन चलता है; रविवार को कुछ जार बना लें।"},"diet":"veg"},{"id":"french-toast","region":"global","art":"stack","hue":"#c7893a","time":15,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["breakfast","sweet","kids","quick"],"alias":["french toast","sweet toast","eggy bread","फ्रेंच टोस्ट"],"title":{"en":"French Toast","hi":"फ्रेंच टोस्ट","mr":"फ्रेंच टोस्ट","gu":"ફ્રેન્ચ ટોસ્ટ","ta":"ஃபிரெஞ்ச் டோஸ்ட்"},"desc":{"en":"Bread soaked in a cinnamon-vanilla egg custard and pan-fried in butter.","hi":"दालचीनी-वनीला वाले अंडे के घोल में डुबोकर मक्खन में सेकी ब्रेड।"},"ing":[["bread",4,"pc"],["eggs",2,"pc"],["milk",0.33,"cup"],["sugar",1,"tbsp"],["cinnamon_powder",0.5,"tsp"],["vanilla",0.5,"tsp"],["butter",2,"tbsp"],["honey",2,"tbsp"]],"steps":[{"en":"Whisk the eggs, milk, sugar, cinnamon and vanilla in a shallow dish.","hi":"चौड़े बर्तन में अंडे, दूध, चीनी, दालचीनी और वनीला फेंटें।"},{"en":"Dip each bread slice for a few seconds per side so it soaks but doesn't fall apart.","hi":"हर ब्रेड स्लाइस को दोनों तरफ़ कुछ सेकंड डुबोएं ताकि घोल सोख ले पर टूटे नहीं।"},{"en":"Cook in butter on medium heat until golden, about 2 minutes per side.","hi":"मक्खन में मध्यम आंच पर सुनहरा होने तक, हर तरफ़ लगभग 2 मिनट सेकें।","t":240},{"en":"Serve warm with honey and fruit.","hi":"शहद और फलों के साथ गरम परोसें।"}],"tip":{"en":"Slightly stale bread soaks up more custard without going soggy.","hi":"थोड़ी बासी ब्रेड ज़्यादा घोल सोखती है और गीली नहीं होती।"},"diet":"egg"},{"id":"banana-smoothie","region":"global","art":"glass","hue":"#e2c35a","time":5,"serves":2,"level":{"en":"Easy","hi":"आसान"},"tags":["drink","breakfast","quick","healthy","kids"],"alias":["banana smoothie","banana shake","kela shake","बनाना शेक","केला शेक","स्मूदी"],"title":{"en":"Banana Oat Smoothie","hi":"बनाना ओट स्मूदी","mr":"केळ्याची स्मूदी","gu":"કેળાની સ્મૂધી","ta":"வாழைப்பழ ஸ்மூத்தி"},"desc":{"en":"Thick, filling smoothie of banana, oats, milk and honey. Breakfast in a glass.","hi":"केला, ओट्स, दूध और शहद की गाढ़ी स्मूदी। गिलास में पूरा नाश्ता।"},"ing":[["banana",2,"pc"],["oats",3,"tbsp"],["milk",1.5,"cup"],["honey",1,"tbsp"],["cinnamon_powder",0.25,"tsp"]],"steps":[{"en":"Peel and slice the bananas. Frozen banana makes it extra thick.","hi":"केले छीलकर काटें। जमा हुआ केला स्मूदी को और गाढ़ा बनाता है।"},{"en":"Blend the bananas, oats, milk, honey and cinnamon until completely smooth, about 1 minute.","hi":"केले, ओट्स, दूध, शहद और दालचीनी को पूरी तरह चिकना होने तक लगभग 1 मिनट मिक्सी में चलाएं।","t":60},{"en":"Pour into glasses and drink right away.","hi":"गिलासों में डालें और तुरंत पिएं।"}],"tip":{"en":"For a vegan smoothie use oat or almond milk and replace honey with dates.","hi":"वीगन स्मूदी के लिए ओट या बादाम का दूध लें और शहद की जगह खजूर।"},"diet":"veg"},{"id":"hummus","region":"global","art":"bowl","hue":"#c8b07a","time":15,"serves":4,"level":{"en":"Easy","hi":"आसान"},"tags":["snack","dip","healthy","protein","party","no-cook"],"alias":["hummus","houmous","chickpea dip","हम्मस","हमस"],"title":{"en":"Hummus","hi":"हम्मस","mr":"हम्मस","gu":"હમસ","ta":"ஹம்மஸ்"},"desc":{"en":"Smooth chickpea and tahini dip with lemon and garlic. Use boiled or canned chickpeas.","hi":"नींबू और लहसुन वाला चिकना काबुली चना और ताहिनी का डिप। उबले या डिब्बाबंद छोले लें।"},"ing":[["chickpeas",0.75,"cup"],["tahini",3,"tbsp"],["lemon",3,"tbsp"],["garlic",2,"pc"],["olive_oil",3,"tbsp"],["cumin",0.5,"tsp"],["water",0.25,"cup"],["salt",1,"taste"],["chilli_powder",0.25,"tsp"]],"steps":[{"en":"Boil the soaked chickpeas until very soft (or rinse canned ones). Keep a little cooking water.","hi":"भीगे छोलों को बहुत नरम होने तक उबालें (या डिब्बाबंद धो लें)। थोड़ा पकाने का पानी रख लें।"},{"en":"Blend the tahini and lemon juice for 1 minute until creamy.","hi":"ताहिनी और नींबू रस को 1 मिनट मलाईदार होने तक पीसें।","t":60},{"en":"Add the chickpeas, garlic, cumin, salt and 2 tablespoons of olive oil. Blend, adding cold water a spoon at a time, until very smooth.","hi":"छोले, लहसुन, जीरा, नमक और 2 बड़े चम्मच ऑलिव ऑयल डालें। एक-एक चम्मच ठंडा पानी डालते हुए बहुत चिकना होने तक पीसें।","t":120},{"en":"Spread in a bowl, drizzle the remaining oil and dust with chilli powder. Serve with pita, veggies or chips.","hi":"कटोरे में फैलाएं, ऊपर बचा तेल डालें और लाल मिर्च छिड़कें। पीटा, सब्ज़ियों या चिप्स के साथ परोसें।"}],"tip":{"en":"Ice-cold water while blending makes hummus fluffier.","hi":"पीसते समय बर्फ़ जैसा ठंडा पानी डालने से हम्मस हल्का और फूला बनता है।"},"diet":"veg"}];
